// 영어 독해 단원 (중1·중2) — ENG.add 호출만 사용

ENG.add('m1', '독해: 글의 목적 찾기(편지·안내문)', {
  sub: '글쓴이가 왜 썼는지 신호어로 찾기',
  kw: ['글의 목적', '편지', '안내문', '초대', '감사', '사과', '요청', 'Could you ~?'],
  sections: [
    { h: '글의 목적이란?',
      p: '<b>글의 목적</b>은 글쓴이가 <span class="hl">왜 이 글을 썼는지</span>를 말한다. 편지, 이메일, 문자 메시지, 안내문처럼 받는 사람이 있는 글은 반드시 목적이 있다. 초대하려고, 고마움을 전하려고, 사과하려고, 무엇을 부탁하려고, 어떤 소식을 알리려고 쓴다.',
      table: { head: ['목적', '신호어/단서', '예문'], rows: [['초대', 'invite, Can you come ~?, Please join us', 'Can you come to my party?'], ['감사', 'Thank you for ~, I really appreciate ~', 'Thank you for your help.'], ['사과', "I'm sorry for[about] ~, I apologize", "I'm sorry I was late."], ['요청·부탁', 'Could you ~?, Please ~, I would like ~', 'Could you turn down the music?'], ['안내·알림', 'Attention, We want to let you know ~', 'The library will be closed on Monday.'], ['모집·광고', 'looking for, join, Sign up', 'We are looking for new members!']], cap: '목적별 신호어' },
      ex: [["I'm writing to invite you to our class concert.", '우리 반 음악회에 초대하려고 편지를 씁니다.'], ['Could you please return my book by Friday?', '금요일까지 제 책을 돌려주시겠어요?']] },
    { h: '목적 찾기 풀이 순서',
      p: '편지나 안내문은 처음에 인사나 자기소개, 지난 이야기가 나오고 <span class="hl">목적은 중간이나 끝</span>에 나오는 경우가 많다. 그래서 첫 문장만 보고 답을 고르면 틀리기 쉽다.',
      table: { head: ['순서', '할 일', '확인할 점'], rows: [['1', '받는 사람·보내는 사람 확인', 'Dear ~ / From ~ : 누가 누구에게 쓰는가'], ['2', '글의 종류 파악', '편지, 문자, 공지, 광고 중 무엇인가'], ['3', '신호어 찾기', 'Please, Could you, I want to, I\'m writing to'], ['4', '마지막 부분 꼭 읽기', '부탁·초대는 끝에 나오는 경우가 많다'], ['5', '보기 고르기', '글의 일부만 담은 보기는 지운다']], cap: '목적 찾기 5단계' },
      ex: [['Thank you for teaching us. Could you join our class party?', '가르쳐 주셔서 감사해요. 반 파티에 와 주시겠어요? (진짜 목적: 초대)']],
      tip: '"I\'m writing to ~ (~하려고 글을 씁니다)" 뒤에는 목적이 그대로 나온다.' },
    { h: '자주 하는 실수',
      p: '목적 문제의 오답은 대부분 <b>글에 나온 내용이지만 목적은 아닌 것</b>이다. 글쓴이가 결국 받는 사람에게 무엇을 원하는지 생각해야 한다.',
      table: { head: ['실수', '예', '바른 판단'], rows: [['첫 인사를 목적으로 착각', 'How are you? I\'m doing well.', '안부 인사는 목적이 아니다'], ['배경 설명을 목적으로 착각', 'I study at night. (사정 설명)', '뒤에 나오는 부탁이 목적'], ['감사 표현만 보고 고르기', 'Thank you for ~. Could you ~?', '감사 뒤의 부탁이 진짜 목적'], ['낱말 하나만 보고 고르기', 'music이 나와서 "음악 소개"', '글 전체가 원하는 것을 본다']] },
      ex: [["I live right below you. Could you please be quiet after 10 p.m.?", '저는 바로 아래층에 살아요. 밤 10시 이후에는 조용히 해 주시겠어요? (목적: 요청)']],
      warn: '"~을 소개하려고", "~을 자랑하려고"처럼 글의 일부 내용만 담은 보기를 조심한다.' },
  ],
  bank: [
    { lv: 1, q: '다음 문장을 쓴 목적으로 알맞은 것은?<div class="passage">Thank you so much for the birthday present. I love it!</div>', o: ['감사', '사과', '초대', '불평'], a: 0, why: 'Thank you for ~는 고마움을 전하는 표현이다.' },
    { lv: 1, q: '다음 문장을 쓴 목적으로 알맞은 것은?<div class="passage">My birthday party is this Saturday at 2 p.m. Can you come?</div>', o: ['사과', '요청', '초대', '감사'], a: 2, why: '파티 날짜를 알려 주고 Can you come?(올 수 있니?)이라고 물으므로 초대하는 글이다.' },
    { lv: 1, q: '사과하는 글에서 자주 쓰는 표현은?', o: ['Thank you for ~', 'Please join us', "Don't forget to ~", "I'm sorry for ~"], a: 3, why: "I'm sorry for ~는 미안함을 나타내는 사과 표현이다. ①은 감사, ②는 초대, ③은 당부 표현이다." },
    { lv: 2, q: `다음 편지의 목적으로 알맞은 것은?<div class="passage">✉️<br>Dear Ms. Kim,<br>I want to say thank you. When I first came to this school, I had no friends. You always smiled at me and helped me in class. Now I have many friends, and I love school. You are the best teacher!<br>Love, Jiwoo</div>`, o: ['새 친구를 소개하려고', '선생님께 감사하려고', '전학 소식을 알리려고', '수업 시간을 물어보려고'], a: 1, why: '첫 문장 I want to say thank you와 선생님이 도와주신 일을 통해 감사 편지임을 알 수 있다.' },
    { lv: 2, q: `다음 안내문의 목적으로 알맞은 것은?<div class="passage">🏫📢<br>Attention, students! The school library will be closed next Monday and Tuesday because we are getting new bookshelves. Please return your books by this Friday. The library will open again on Wednesday. Thank you.</div>`, o: ['도서관 이용 시간을 늘리려고', '새 책을 추천하려고', '책장 기부를 부탁하려고', '도서관 임시 휴관을 알리려고'], a: 3, why: '새 책장 때문에 월·화요일에 도서관 문을 닫는다는 것을 알리는 안내문이다. 책장 기부 이야기는 없다.' },
    { lv: 2, q: `다음 메시지의 목적으로 알맞은 것은?<div class="passage">📱<br>Hi Minho, I'm really sorry about yesterday. I broke your pencil case by mistake when I was running in the classroom. I bought a new one for you. I'll give it to you tomorrow. I hope you're not angry. — Sora</div>`, o: ['사과하려고', '필통을 빌리려고', '교실 규칙을 알리려고', '생일을 축하하려고'], a: 0, why: "I'm really sorry about yesterday로 시작해 필통을 망가뜨린 일을 사과하고 있다." },
    { lv: 3, q: `다음 편지의 목적으로 알맞은 것은?<div class="passage">✉️🏢<br>Dear neighbor in 302,<br>Hello, I live in 202, right below you. I am a middle school student, and I study for tests at night. These days, I often hear loud music from your home after 11 p.m. Could you please turn it down late at night? Thank you for understanding.<br>From Hayun in 202</div>`, o: ['이사 온 것을 알리려고', '시험공부를 도와 달라고 하려고', '밤늦게 음악 소리를 줄여 달라고 부탁하려고', '함께 음악을 듣자고 하려고'], a: 2, why: '앞부분은 자기 사정 설명이고, Could you please turn it down ~?에서 소리를 줄여 달라는 진짜 목적이 나온다.' },
    { lv: 3, q: `다음 글의 목적으로 알맞은 것은?<div class="passage">🎸🥁🎹<br>Do you like music? Can you play the guitar, drums, or keyboard? Our school band, Blue Notes, is looking for new members! We practice every Wednesday after school in the music room. No experience? No problem! We will teach you. Come and visit us this Wednesday at 4 p.m.</div>`, o: ['학교 밴드의 새 부원을 모집하려고', '음악실 위치를 알려 주려고', '밴드 공연 날짜를 알리려고', '악기를 팔려고'], a: 0, why: 'is looking for new members와 Come and visit us로 보아 부원 모집 글이다. 공연 날짜는 나오지 않는다.' },
    { lv: 3, q: `다음 편지에서 글쓴이의 목적이 가장 잘 드러난 문장은?<div class="passage">① Last Saturday, I visited your shop to buy a backpack. ② The clerk was very kind and helpful. ③ But when I got home, I found a big hole at the bottom of the bag. ④ I would like to get a new one or my money back.</div>`, o: ['①', '②', '③', '④'], a: 3, why: '①~③은 있었던 일을 설명하고, ④에서 새 가방이나 환불을 원한다는 목적(요청)을 밝힌다.' },
    { lv: 4, q: `다음 편지의 목적으로 가장 알맞은 것은?<div class="passage">✉️👵<br>Dear Grandma,<br>How are you? I'm doing well at my new school. I joined the dance club, and I practice hard every day. Guess what! Our school festival is on May 20, and my club is going to dance on stage. It starts at 2 p.m. in the gym. Can you come and watch me? It would mean a lot to me.<br>Love, Yuna</div>`, o: ['댄스 동아리 가입을 자랑하려고', '학교 축제 공연에 할머니를 초대하려고', '새 학교생활이 힘들다고 말하려고', '할머니의 건강을 걱정하려고'], a: 1, why: '안부와 동아리 소식 뒤에 Can you come and watch me?라고 공연에 와 달라고 초대한다. ①은 글의 일부 내용일 뿐이다.' },
    { lv: 4, q: `다음 안내문의 목적으로 가장 알맞은 것은?<div class="passage">🚌📅<br>Dear parents,<br>Our class field trip to the science museum was planned for this Thursday. However, the weather report says it will rain heavily that day. So we have decided to move the trip to next Tuesday, October 15. Students should still bring their lunch and wear comfortable shoes. Thank you.<br>— Mr. Park, Class 1-3 teacher</div>`, o: ['과학관 관람 후기를 전하려고', '도시락 메뉴를 정하려고', '현장 학습 날짜가 바뀐 것을 알리려고', '비 오는 날의 등교 시간을 알리려고'], a: 2, why: 'However와 So 뒤에서 비 때문에 현장 학습을 다음 주 화요일로 옮긴다고 알린다.' },
    { lv: 4, q: `다음 편지의 목적으로 가장 알맞은 것은?<div class="passage">✉️🌳<br>To the City Office,<br>I live near Sunny Park, and I take a walk there every evening. The park is beautiful, but there are not enough trash cans. People leave cups and bags on the benches, and the park gets dirty. Please put some more trash cans in the park. Thank you.<br>Kim Taeho</div>`, o: ['공원 산책을 권하려고', '공원에 쓰레기통을 더 놓아 달라고 요청하려고', '공원 청소 봉사자를 모집하려고', '공원 벤치 교체를 알리려고'], a: 1, why: '쓰레기통이 부족해 공원이 더러워진다는 문제를 말한 뒤 Please put some more trash cans로 요청한다.' },
    { lv: 5, q: `다음 편지의 목적으로 가장 알맞은 것은?<div class="passage">✉️🎥<br>Dear Mr. Lee,<br>Thank you for teaching us science this year. Your classes were always fun. I'm writing because our class is making a video for the school's 50th birthday. We want to interview teachers about the school's history, and you have worked here the longest. Could you spare 20 minutes next week for an interview? Please let me know a good time.<br>Best, Seojun, Class 2-1</div>`, o: ['과학 수업에 감사하려고', '학교 생일 축하 영상을 보여 주려고', '다음 주 수업 시간을 바꾸려고', '학교 역사에 대한 인터뷰를 부탁하려고'], a: 3, why: "I'm writing because ~ 뒤에서 이유를 밝히고 Could you spare 20 minutes ~?로 인터뷰를 부탁한다. 첫 문장의 감사는 인사일 뿐이다." },
    { lv: 5, q: `다음 글의 목적으로 가장 알맞은 것은?<div class="passage">🔎🎒<br>Lost Bag!<br>I lost my blue backpack on the school bus last Friday afternoon. It has a small yellow star key ring on it. Inside, there are my math notebook and a pencil case with my name, Lee Dana. The notebook is very important because I have to study for the test. If you find it, please bring it to Class 1-5.</div>`, o: ['잃어버린 가방을 찾아 달라고 부탁하려고', '중고 가방을 팔려고', '수학 공부 방법을 알리려고', '통학 버스 시간을 안내하려고'], a: 0, why: '가방을 잃어버린 때와 생김새를 설명하고 If you find it, please bring it ~으로 찾아 달라고 부탁한다.' },
    { lv: 5, q: `다음 메시지의 목적으로 가장 알맞은 것은?<div class="passage">📱<br>Hi Eunji, thanks for inviting me to your sleepover on Saturday. I really wanted to go, but my family is visiting my uncle in Busan this weekend. We'll leave early Saturday morning and come back on Sunday night. I'm so sorry. How about going to the movies together next weekend instead? Let me know!<br>— Hana</div>`, o: ['파자마 파티에 초대하려고', '부산 여행을 함께 가자고 하려고', '초대를 거절하고 다른 날 만나자고 제안하려고', '영화표를 예매해 달라고 부탁하려고'], a: 2, why: '가족 일정 때문에 못 간다고 거절한 뒤 How about ~ next weekend?로 다른 약속을 제안한다. 초대한 사람은 은지이다.' },
  ],
});

ENG.add('m1', '독해: 세부 정보 찾기', {
  sub: '질문의 의문사로 필요한 정보만 골라 읽기',
  kw: ['세부 정보', '의문사', 'scanning', '숫자·시간', '계산', '답할 수 없는 질문', '언급되지 않은 것'],
  sections: [
    { h: '질문이 무엇을 묻는지 먼저 본다',
      p: '세부 정보 문제는 글 전체의 뜻보다 <b>질문이 묻는 정보 하나</b>를 정확히 찾는 문제이다. 질문의 <span class="hl">의문사</span>를 보면 무엇을 찾아야 하는지 알 수 있다.',
      table: { head: ['의문사', '찾을 정보', '본문에서 찾을 단서'], rows: [['Who', '사람', '이름, he/she, my brother'], ['When / What time', '때·시각', 'on Monday, at 3:20, last week'], ['Where', '장소', 'at the park, in Busan'], ['What', '물건·일', '명사, 동사(ate, bought)'], ['How many / How much', '수량 / 가격', '숫자, won, each, free'], ['Why', '이유', 'because, so']], cap: '의문사별로 찾을 정보' },
      ex: [['When does the class start? — It starts at 5 p.m.', '수업은 언제 시작하니? — 오후 5시에 시작해.'], ['How much is the ticket? — It is 3,000 won.', '표는 얼마니? — 3,000원이야.']] },
    { h: '훑어 읽기(scanning) 풀이 순서',
      p: '모든 문장을 꼼꼼히 해석할 필요는 없다. 질문의 핵심어를 기억한 채 본문을 <span class="hl">빠르게 훑어</span> 그 핵심어가 나오는 문장만 자세히 읽는다.',
      table: { head: ['순서', '할 일', '예'], rows: [['1', '질문의 의문사와 핵심어 표시', 'What did the writer <b>eat</b>?'], ['2', '본문에서 핵심어(또는 비슷한 말) 찾기', 'eat → ate'], ['3', '그 문장과 앞뒤 문장 자세히 읽기', 'Then we ate ramyeon.'], ['4', '숫자는 조건까지 확인해 계산', '3개 사면 1개 무료'], ['5', '보기와 한 번 더 대조', '시간·사람이 바뀌지 않았는지']], cap: '세부 정보 찾기 5단계' },
      ex: [['We rode bikes for two hours.', '우리는 두 시간 동안 자전거를 탔다. (How long?의 답)']],
      tip: '질문의 동사는 본문에서 과거형이나 비슷한 말로 바뀌어 나올 수 있다. (buy → bought, start → begin)' },
    { h: '자주 하는 실수',
      p: '세부 정보 문제의 오답은 <b>본문에 나온 다른 숫자·사람·장소</b>로 만든다. 또 "답할 수 없는 질문" 문제는 본문에 정보가 <span class="hl">없는</span> 것을 골라야 한다.',
      table: { head: ['실수', '예', '바른 방법'], rows: [['다른 숫자를 고름', '3:00(약속) ↔ 3:20(도착)', '질문이 묻는 대상의 숫자인지 확인'], ['계산을 안 함', '40 minutes late', '7:00 + 40분 = 7:40'], ['조건을 놓침', 'one cookie free', '무료 조건을 빼고 계산'], ['상식으로 답함', '카메라 가격은 비쌀 것이다', '본문에 없으면 "알 수 없음"'], ['인물을 섞음', '세 친구의 주말', '이름과 행동을 짝지어 표시']] },
      warn: '"글을 읽고 답할 수 없는 질문"은 본문에 근거가 하나도 없는 질문을 고르는 것이다. 그럴듯해도 글에 없으면 답할 수 없다.' },
  ],
  bank: [
    { lv: 1, q: '"When does the class start?"에 답하려면 본문에서 무엇을 찾아야 하는가?', o: ['장소', '시각', '사람', '이유'], a: 1, why: 'When은 "언제"를 묻는 의문사이므로 시각·날짜를 찾아야 한다.' },
    { lv: 1, q: `다음 글을 읽고, Where does Mina live?에 대한 답으로 알맞은 것은?<div class="passage">My name is Mina. I am 14 years old. I live in Daejeon with my parents and a cat. I like drawing and singing.</div>`, o: ['Seoul', 'Busan', 'Daejeon', 'Incheon'], a: 2, why: 'I live in Daejeon에서 미나가 사는 곳을 알 수 있다.' },
    { lv: 1, q: '"How much is the ticket?"에 답하려면 본문에서 무엇을 찾아야 하는가?', o: ['날짜', '사람 수', '장소', '가격'], a: 3, why: 'How much는 가격(얼마)을 묻는다. 사람 수는 How many로 묻는다.' },
    { lv: 2, q: `다음 일기를 읽고, 글쓴이가 먹은 것은?<div class="passage">📔🚲<br>Today was Sunday. I went to the Han River with my brother. We rode bikes for two hours. Then we ate ramyeon at a convenience store. It was cold, but the ramyeon was hot and delicious. I want to go again next weekend.</div>`, o: ['ramyeon', 'gimbap', 'chicken', 'sandwiches'], a: 0, why: 'Then we ate ramyeon at a convenience store에서 라면을 먹었다는 것을 알 수 있다.' },
    { lv: 2, q: `다음 글을 읽고 알 수 <b>없는</b> 것은?<div class="passage">🐶<br>I have a dog named Coco. She is three years old. She has white fur and brown ears. Every morning, my dad walks her in the park before work. Coco loves chicken snacks, but she hates baths.</div>`, o: ['개의 이름', '개를 처음 데려온 곳', '개의 나이', '아침 산책을 시키는 사람'], a: 1, why: '이름(Coco), 나이(three), 산책시키는 사람(my dad)은 나오지만 개를 어디서 데려왔는지는 나오지 않는다.' },
    { lv: 2, q: `다음 안내문을 읽고, 수영 수업은 일주일에 몇 번 있는가?<div class="passage">🏊<br>Sunshine Swimming Class<br>For: students aged 10 to 15<br>When: every Tuesday and Thursday, 5–6 p.m.<br>Where: City Sports Center<br>Fee: 30,000 won a month<br>Bring your own swimming cap!</div>`, o: ['once a week', 'every day', 'three times a week', 'twice a week'], a: 3, why: '화요일과 목요일, 일주일에 두 번(twice a week) 수업이 있다.' },
    { lv: 3, q: `다음 메시지를 읽고, Tae가 영화관에 도착할 시각은?<div class="passage">📱🎬<br>Hey Junho, I'm at the bus stop now, but the bus is late. I think I'll get to the cinema at 3:20, not 3:00. The movie starts at 3:30, so we still have time. Can you buy popcorn first? I'll pay you back. — Tae</div>`, o: ['3:00', '3:30', '3:20', '3:50'], a: 2, why: "I'll get to the cinema at 3:20, not 3:00에서 도착 시각은 3시 20분이다. 3:00은 원래 약속, 3:30은 영화 시작 시각이다." },
    { lv: 3, q: `다음 광고를 읽고, Mina가 컵케이크 3개와 쿠키 2개를 샀을 때 낸 돈은?<div class="passage">🧁🍪<br>Grand Opening Sale at Sweet Bakery!<br>Cupcakes are 2,000 won each. Cookies are 1,000 won each. Today only, if you buy three cupcakes, you get one cookie free.</div>`, o: ['6,000 won', '7,000 won', '8,000 won', '9,000 won'], a: 1, why: '컵케이크 3개는 6,000원이고, 3개를 사면 쿠키 1개가 무료이므로 쿠키는 1개 값(1,000원)만 낸다. 6,000 + 1,000 = 7,000원.' },
    { lv: 3, q: `다음 글을 읽고 답할 수 <b>없는</b> 질문은?<div class="passage">📷<br>Sujin's hobby is taking pictures. She got a camera from her aunt last year. She takes pictures of flowers, birds, and the sky. On weekends, she goes to the mountain near her house with her camera. She wants to be a photographer someday.</div>`, o: ["What is Sujin's hobby?", 'Who gave Sujin a camera?', 'Where does Sujin go on weekends?', "How much was Sujin's camera?"], a: 3, why: '취미(taking pictures), 카메라를 준 사람(her aunt), 주말에 가는 곳(the mountain)은 나오지만 카메라 가격은 나오지 않는다.' },
    { lv: 4, q: `다음 글을 읽고, 미역국을 끓인 사람은?<div class="passage">🎂🍲<br>Last Saturday was my mom's birthday. My sister and I wanted to surprise her. In the morning, Dad took Mom to the market. While they were out, we made seaweed soup together. My sister cut the vegetables, and I cooked the soup. When Mom came back at noon, she saw the table and smiled. She said it was the best birthday ever.</div>`, o: ['Dad', 'the writer', 'Mom', "the writer's sister"], a: 1, why: 'My sister cut the vegetables, and I cooked the soup에서 국을 끓인 사람은 글쓴이(I)이다. 여동생(언니)은 채소를 썰었다.' },
    { lv: 4, q: `다음 글에서 답을 찾을 수 <b>있는</b> 질문은?<div class="passage">🌻<br>The sunflower is a big, bright flower. It can grow up to three meters tall. Young sunflowers turn their heads to follow the sun across the sky. Their seeds are healthy food for people and birds. Many sunflowers are grown in Russia and Ukraine.</div>`, o: ['How tall can a sunflower grow?', 'When do sunflowers bloom?', 'How much water do sunflowers need?', 'Who named the sunflower?'], a: 0, why: 'It can grow up to three meters tall에서 키가 3미터까지 자란다는 답을 찾을 수 있다. 나머지는 글에 없다.' },
    { lv: 4, q: `다음 안내문을 읽고, 상을 받는 학생은 모두 몇 명인가?<div class="passage">🎨🏆<br>Drawing Contest for Students<br>Theme: My Dream Town<br>Who: middle school students in Green City<br>How: Draw your picture on A3 paper and send a photo of it by email by June 10.<br>Prizes: The first prize winner gets a tablet PC. Ten other students will get art sets.<br>Winners will be announced on our website on June 25.</div>`, o: ['1', '10', '11', '25'], a: 2, why: '1등 1명 + 미술 세트를 받는 다른 학생 10명 = 11명이다. 25는 발표 날짜이다.' },
    { lv: 5, q: `다음 글을 읽고, 오늘 아침 Minji가 일어난 시각은?<div class="passage">⏰🚌<br>Minji usually wakes up at 7:00. But this morning, her alarm didn't ring, and she woke up 40 minutes late. She didn't eat breakfast and ran to the bus stop. Luckily, the bus came five minutes later. She arrived at school at 8:20, just in time for her first class.</div>`, o: ['7:00', '7:45', '8:20', '7:40'], a: 3, why: '평소 7시보다 40분 늦게 일어났으므로 7시 40분이다. 7:45는 5분을 잘못 더한 것, 8:20은 학교 도착 시각이다.' },
    { lv: 5, q: `다음 글을 읽고, 학생들이 준비해야 할 것을 바르게 짝지은 것은?<div class="passage">🏖️🧤<br>Hi everyone! Our class will clean the beach this Saturday. We will meet in front of the school at 9 a.m. and take the bus together. The cleaning will take about three hours, so we'll finish around noon. After that, we will have lunch together at a restaurant near the beach. Please wear a hat and bring gloves. Don't bring plastic water bottles. We'll give each of you a free tumbler!</div>`, o: ['hat, gloves', 'gloves, water bottle', 'tumbler, hat', 'lunch, gloves'], a: 0, why: '모자를 쓰고 장갑을 가져오라고 했다. 물병은 가져오지 말라고 했고, 텀블러는 나누어 주며, 점심은 식당에서 먹는다.' },
    { lv: 5, q: `다음 글을 읽고, 주말에 집에만 있었던 사람은?<div class="passage">🗓️<br>Three friends talked about their weekend. Dohun said he watched a baseball game with his dad. Yerin didn't go out because she had a cold. She read comic books at home all day. Siwoo visited his grandparents' farm and picked strawberries. He brought some to school on Monday and shared them with Dohun and Yerin.</div>`, o: ['Dohun', 'Siwoo', "Dohun's dad", 'Yerin'], a: 3, why: '예린은 감기 때문에 나가지 않고(didn\'t go out) 집에서 만화책을 읽었다. 도훈은 야구 경기를 보러 갔고 시우는 농장에 갔다.' },
  ],
});

ENG.add('m1', '독해: 그림·표 보고 답하기', {
  sub: '제목·항목·단위를 먼저 보고 칸을 찾기',
  kw: ['그림', '표', '시간표', '가격표', '설문 결과', 'the most', 'more than', 'twice'],
  sections: [
    { h: '그림·표 문제의 종류',
      p: '그림·표 문제는 글 대신 <b>그림, 시간표, 가격표, 설문 결과</b> 같은 자료를 보고 답한다. 자료에 있는 사실만으로 판단해야 하며, 표의 <span class="hl">제목·항목·단위</span>를 먼저 확인하는 것이 중요하다.',
      table: { head: ['종류', '묻는 것', '예'], rows: [['그림 묘사', '그림과 맞는 문장', '🍎🍎🍎 → There are three apples.'], ['시간표·일정표', '요일·시각 찾기', 'What is the 3rd class on Wednesday?'], ['가격표·메뉴', '가격 찾기, 계산', 'How much are two tickets?'], ['설문·기록 표', '가장 많은 것, 비교', 'Which sport is the most popular?']], cap: '그림·표 문제 유형' },
      ex: [['There are three apples and two bananas on the table.', '탁자 위에 사과 세 개와 바나나 두 개가 있다.'], ['Soccer is the most popular sport in our class.', '축구는 우리 반에서 가장 인기 있는 운동이다.']] },
    { h: '표를 읽는 순서',
      p: '표는 한꺼번에 다 보려고 하면 헷갈린다. <span class="hl">가로줄과 세로줄이 만나는 칸</span>을 찾는다고 생각하면 쉽다.',
      table: { head: ['순서', '할 일', '단서'], rows: [['1', '표의 제목 읽기', '무엇에 대한 표인가 (Favorite Sports)'], ['2', '가로·세로 항목 확인', '요일, 교시, 이름, 과목'], ['3', '단위 확인', 'won, hours, students, %'], ['4', '질문의 핵심어로 칸 찾기', 'Wednesday + 3rd → Music'], ['5', '조건이 있으면 계산', '할인, 소요 시간, 나이 제한']], cap: '표 읽기 5단계' },
      ex: [['The bus leaves at 8:40, and the ride takes 25 minutes.', '버스는 8시 40분에 출발하고 25분이 걸린다. (도착 9:05)']],
      tip: '시간표 문제는 출발 시각에 걸리는 시간을 더해 도착 시각을 꼭 계산한다.' },
    { h: '비교 표현과 자주 하는 실수',
      p: '표의 내용을 문장으로 바꾼 보기에는 <b>비교 표현</b>이 많이 나온다. 숫자를 정확히 비교해야 한다.',
      table: { head: ['표현', '뜻', '확인할 점'], rows: [['the most / the fewest', '가장 많은 / 가장 적은', '가장 큰·작은 숫자 하나뿐인가'], ['more than / less than', '~보다 많은 / 적은', '어느 쪽이 큰지 방향 확인'], ['twice / half', '두 배 / 절반', '정확히 계산 (15는 10의 두 배가 아니다)'], ['the same as', '~와 같은', '두 숫자가 정말 같은가'], ['increase / decrease', '늘다 / 줄다', '매달 계속 늘었는지 확인']], cap: '표에 자주 나오는 비교 표현' },
      ex: [['Sara sleeps two hours more than Minho.', '사라는 민호보다 두 시간 더 잔다.'], ['Students read the fewest books in March.', '학생들은 3월에 책을 가장 적게 읽었다.']],
      warn: '다른 줄(행)의 숫자를 읽는 실수, "두 배"를 대충 판단하는 실수가 가장 많다.' },
  ],
  bank: [
    { lv: 1, q: `그림에 맞는 문장은?<div class="passage">🍎🍎🍎 🍌🍌</div>`, o: ['There are three apples and two bananas.', 'There are two apples and three bananas.', 'There is one apple and two bananas.', 'There are three bananas.'], a: 0, why: '사과(🍎)가 세 개, 바나나(🍌)가 두 개 있다.' },
    { lv: 1, q: `다음 일기 예보를 보고, 화요일의 날씨로 알맞은 것은?<div class="passage"><table><tr><th>Mon</th><th>Tue</th><th>Wed</th></tr><tr><td>☀️</td><td>🌧️</td><td>☁️</td></tr></table></div>`, o: ['sunny', 'cloudy', 'rainy', 'snowy'], a: 2, why: '화요일(Tue)에는 비 그림(🌧️)이 있으므로 rainy이다.' },
    { lv: 1, q: `다음 가격표를 보고, 공책은 얼마인가?<div class="passage">✏️📒<table><tr><th>Item</th><th>Price</th></tr><tr><td>pencil</td><td>500 won</td></tr><tr><td>notebook</td><td>1,500 won</td></tr><tr><td>eraser</td><td>700 won</td></tr></table></div>`, o: ['500 won', '700 won', '1,000 won', '1,500 won'], a: 3, why: 'notebook(공책) 줄의 가격은 1,500원이다.' },
    { lv: 2, q: `다음 시간표를 보고, 수요일 3교시 과목은?<div class="passage">🏫<table><tr><th>Period</th><th>Monday</th><th>Wednesday</th></tr><tr><td>1</td><td>Korean</td><td>Science</td></tr><tr><td>2</td><td>Math</td><td>English</td></tr><tr><td>3</td><td>English</td><td>Music</td></tr><tr><td>4</td><td>P.E.</td><td>Math</td></tr></table></div>`, o: ['English', 'Music', 'Math', 'Science'], a: 1, why: 'Wednesday 열과 3교시 행이 만나는 칸은 Music이다. English는 월요일 3교시이다.' },
    { lv: 2, q: `다음 표를 보고, 반에서 가장 인기 있는 운동은?<div class="passage">⚽🏀⚾🏸<br>Favorite Sports of Class 1-2<table><tr><th>Sport</th><th>Students</th></tr><tr><td>Soccer</td><td>12</td></tr><tr><td>Basketball</td><td>8</td></tr><tr><td>Baseball</td><td>5</td></tr><tr><td>Badminton</td><td>5</td></tr></table></div>`, o: ['basketball', 'baseball', 'badminton', 'soccer'], a: 3, why: '축구(Soccer)를 좋아하는 학생이 12명으로 가장 많다.' },
    { lv: 2, q: `그림의 내용과 일치하는 문장은?<div class="passage">👧 Mina — 🎹<br>👦 Jiho — ⚽<br>👧 Yuri — 🎨</div>`, o: ['Yuri is drawing a picture.', 'Mina is playing soccer.', 'Jiho is playing the piano.', 'Jiho is drawing a picture.'], a: 0, why: '유리 옆에 그림 도구(🎨)가 있으므로 그림을 그리고 있다. 미나는 피아노, 지호는 축구를 하고 있다.' },
    { lv: 3, q: `다음 점심 메뉴표의 내용과 일치하지 <b>않는</b> 것은?<div class="passage">🍱 This Week's Lunch Menu<table><tr><th>Day</th><th>Main</th><th>Dessert</th></tr><tr><td>Mon</td><td>Bibimbap</td><td>Apple</td></tr><tr><td>Tue</td><td>Curry rice</td><td>Yogurt</td></tr><tr><td>Wed</td><td>Spaghetti</td><td>Ice cream</td></tr><tr><td>Thu</td><td>Fried rice</td><td>Banana</td></tr><tr><td>Fri</td><td>Bulgogi</td><td>Cake</td></tr></table></div>`, o: ['Students eat curry rice on Tuesday.', 'Ice cream is the dessert on Wednesday.', 'Students have spaghetti on Thursday.', 'There is cake on Friday.'], a: 2, why: '스파게티는 수요일(Wed) 메뉴이고, 목요일(Thu)에는 볶음밥(Fried rice)이 나온다.' },
    { lv: 3, q: `다음 표의 내용과 일치하는 것은?<div class="passage">😴 Hours of Sleep Last Night<table><tr><th>Name</th><th>Hours</th></tr><tr><td>Minho</td><td>7</td></tr><tr><td>Sara</td><td>9</td></tr><tr><td>Jun</td><td>6</td></tr><tr><td>Dana</td><td>8</td></tr></table></div>`, o: ['Jun slept the most.', 'Dana slept less than Jun.', 'Sara slept two hours more than Minho.', 'Minho and Dana slept the same hours.'], a: 2, why: '사라는 9시간, 민호는 7시간이므로 두 시간 더 잤다. 가장 많이 잔 사람은 사라이고, 준은 가장 적게 잤다.' },
    { lv: 3, q: `다음 버스 시간표를 보고, 9시 30분까지 시청에 도착하려면 탈 수 있는 가장 늦은 버스는?<div class="passage">🚌 Bus 15 to City Hall<table><tr><th>Departure</th></tr><tr><td>8:10</td></tr><tr><td>8:40</td></tr><tr><td>9:10</td></tr><tr><td>9:40</td></tr></table>The ride to City Hall takes 25 minutes.</div>`, o: ['8:10', '8:40', '9:10', '9:40'], a: 1, why: '9:10 버스는 25분 뒤인 9:35에 도착해 늦는다. 8:40 버스는 9:05에 도착하므로 이것이 가장 늦게 탈 수 있는 버스이다.' },
    { lv: 4, q: `다음 안내표를 보고, 14살이고 금요일과 토요일에만 시간이 되는 Jiwon이 참여할 수 있는 프로그램은?<div class="passage">📚 City Library Programs<table><tr><th>Program</th><th>Day</th><th>Time</th><th>Age</th></tr><tr><td>English Storytelling</td><td>Mon</td><td>4–5 p.m.</td><td>8–10</td></tr><tr><td>Book Club</td><td>Wed</td><td>5–6 p.m.</td><td>13–15</td></tr><tr><td>Comic Drawing</td><td>Fri</td><td>4–6 p.m.</td><td>12–16</td></tr><tr><td>Movie Night</td><td>Sat</td><td>6–8 p.m.</td><td>all ages</td></tr></table></div>`, o: ['Book Club only', 'English Storytelling and Book Club', 'Movie Night only', 'Comic Drawing and Movie Night'], a: 3, why: '금요일 Comic Drawing(12~16세)과 토요일 Movie Night(모든 나이)에 참여할 수 있다. Book Club은 나이는 맞지만 수요일이다.' },
    { lv: 4, q: `다음 표를 설명한 글에서 표의 내용과 일치하지 <b>않는</b> 문장은?<div class="passage">🚶🚌🚲🚗<br>How Students Get to School<table><tr><th>Way</th><th>Students</th></tr><tr><td>Walk</td><td>45%</td></tr><tr><td>Bus</td><td>30%</td></tr><tr><td>Bike</td><td>15%</td></tr><tr><td>Car</td><td>10%</td></tr></table>① Almost half of the students walk to school. ② The bus is the second most popular way. ③ The number of students who ride bikes is twice the number of students who come by car. ④ Fewer students come by car than by bike.</div>`, o: ['①', '②', '④', '③'], a: 3, why: '자전거는 15%, 자동차는 10%이므로 두 배(20%)가 아니다. ④는 10%가 15%보다 적으므로 맞다.' },
    { lv: 4, q: `다음 요금표를 보고, 화요일에 Mr. Han이 14살 딸, 7살 아들과 영화를 볼 때 내야 할 돈은?<div class="passage">🎬🎟️ Star Cinema Ticket Prices<table><tr><th>Ticket</th><th>Price</th></tr><tr><td>Adult</td><td>12,000 won</td></tr><tr><td>Student (8–18)</td><td>9,000 won</td></tr><tr><td>Child (under 8)</td><td>6,000 won</td></tr></table>Every Tuesday: 2,000 won off every ticket!</div>`, o: ['27,000 won', '21,000 won', '23,000 won', '19,000 won'], a: 1, why: '어른 10,000원 + 학생 7,000원 + 어린이(8세 미만) 4,000원 = 21,000원이다. 할인 전 금액은 27,000원이다.' },
    { lv: 5, q: `다음 표의 내용과 일치하는 것은?<div class="passage">📖 Books Read by Class 1-4 Students<table><tr><th>Month</th><th>Books</th></tr><tr><td>March</td><td>20</td></tr><tr><td>April</td><td>35</td></tr><tr><td>May</td><td>30</td></tr><tr><td>June</td><td>50</td></tr></table></div>`, o: ['The number of books increased every month.', 'Students read more books in May than in April.', 'In June, students read twice as many books as in April.', 'Students read the fewest books in March.'], a: 3, why: '3월이 20권으로 가장 적다. 5월(30)은 4월(35)보다 줄었으므로 ①, ②는 틀리고, 50은 35의 두 배(70)가 아니다.' },
    { lv: 5, q: `다음 층별 안내와 글을 읽고, Yujin이 들를 층을 순서대로 고른 것은?<div class="passage">🏬 Floor Guide<table><tr><th>Floor</th><th>Shops</th></tr><tr><td>4F</td><td>Restaurants, Cinema</td></tr><tr><td>3F</td><td>Books, Toys</td></tr><tr><td>2F</td><td>Clothes, Shoes</td></tr><tr><td>1F</td><td>Cafe, Bakery</td></tr><tr><td>B1</td><td>Supermarket</td></tr></table>Yujin wants to buy a birthday present for her little brother. He loves robots. After that, she will watch a movie with her friends.</div>`, o: ['3F → 4F', '2F → 4F', 'B1 → 3F', '3F → 1F'], a: 0, why: '로봇 장난감은 3층(Toys)에서 사고, 그다음 영화는 4층(Cinema)에서 본다.' },
    { lv: 5, q: `다음 일기 예보와 메시지를 읽고, 두 사람이 소풍 가는 날과 그날의 날씨를 고른 것은?<div class="passage">🧺<table><tr><th></th><th>Saturday</th><th>Sunday</th></tr><tr><td>Weather</td><td>🌧️ 18°C</td><td>☀️ 22°C</td></tr><tr><td>Chance of rain</td><td>80%</td><td>10%</td></tr></table>Dear Jisu, let's go on a picnic this weekend! Look at the weather forecast. Let's go on the day with a lower chance of rain. Don't forget your sunscreen! — Ara</div>`, o: ['Saturday, rainy', 'Saturday, sunny', 'Sunday, sunny', 'Sunday, rainy'], a: 2, why: '비 올 확률이 더 낮은 날(10%)은 일요일이고, 일요일은 맑음(☀️)이다.' },
  ],
});

ENG.add('m1', '독해: 이야기의 흐름 따라가기', {
  sub: '시간 순서·원인과 결과·마음의 변화 읽기',
  kw: ['이야기', '사건 순서', 'First / Then / Finally', 'Suddenly', '원인과 결과', '심경 변화', '이어질 내용'],
  sections: [
    { h: '이야기의 네 가지 요소',
      p: '이야기(story)는 <b>인물</b>이 어떤 <b>배경</b>에서 <b>사건</b>을 겪고 <b>결말</b>에 이르는 글이다. 읽으면서 "누가, 언제·어디서, 무슨 일이, 어떻게 끝났나"를 머릿속에 정리하면 흐름을 놓치지 않는다.',
      table: { head: ['요소', '스스로 묻는 질문', '단서'], rows: [['인물', 'Who?', '이름, he/she, my brother'], ['배경', 'When? Where?', 'On a rainy day, at the beach'], ['사건', 'What happened?', 'found, lost, broke, suddenly'], ['결말', 'How did it end?', 'Finally, In the end, Now']], cap: '이야기의 요소' },
      ex: [['On a rainy day, Seho found a small kitten under a car.', '비 오는 날, 세호는 차 밑에서 작은 새끼 고양이를 발견했다. (배경 + 인물 + 사건)']] },
    { h: '시간 순서 신호어',
      p: '이야기는 대부분 <span class="hl">일어난 순서대로</span>쓴다. 시간을 나타내는 신호어를 따라가면 사건의 순서를 정확히 알 수 있다.',
      table: { head: ['신호어', '뜻', '흐름'], rows: [['First / At first', '먼저 / 처음에는', '시작'], ['Then / Next / After that', '그다음에 / 그 후에', '이어짐'], ['Suddenly', '갑자기', '예상 못 한 사건'], ['Later / A few minutes later', '나중에 / 몇 분 뒤', '시간이 흐름'], ['Finally / In the end', '마침내 / 결국', '끝·결말']], cap: '시간·순서 신호어' },
      ex: [['First, he mixed flour and milk. Then he poured it into a pan.', '먼저 그는 밀가루와 우유를 섞었다. 그다음 그것을 팬에 부었다.'], ['Suddenly, a big dog came out.', '갑자기 큰 개가 나타났다.']],
      tip: 'At first(처음에는) 뒤에는 나중에 바뀌는 마음이나 상황이 자주 온다.' },
    { h: '원인과 결과, 마음의 변화',
      p: '사건에는 <b>원인(왜)</b>과 <b>결과(그래서)</b>가 있다. because, so 같은 말로 이어 준다. 또 인물의 <span class="hl">마음(심경)</span>은 사건에 따라 바뀌므로, 처음 마음과 나중 마음을 각각 나타내는 단서를 찾는다.',
      table: { head: ['마음', '영어', '단서 행동'], rows: [['긴장한', 'nervous', 'heart beating fast, hands shaking'], ['실망한', 'disappointed', 'cried, made a mistake, lost'], ['기쁜·안심한', 'glad, relieved', 'smiled, laughed, jumped up'], ['감동한', 'touched', 'held it tightly, tears in her eyes'], ['절망한', 'hopeless', 'felt like giving up']], cap: '심경을 나타내는 말과 단서' },
      ex: [['She played games until 1 a.m., so she didn\'t hear her alarm.', '그녀는 새벽 1시까지 게임을 해서 알람을 듣지 못했다. (원인 → 결과)'], ['At first, Hajin was nervous. Later, he felt glad.', '처음에 하진은 긴장했다. 나중에 그는 기뻤다.']] },
    { h: '풀이 순서와 자주 하는 실수',
      p: '순서·심경·이어질 내용 문제는 모두 <b>흐름</b>을 묻는다. 한 문장만 보지 말고 앞뒤를 이어서 읽는다.',
      table: { head: ['문제 유형', '풀이 순서', '자주 하는 실수'], rows: [['사건 순서', '신호어에 번호 매기기 → 순서대로 배열', '글에 나온 순서와 일어난 순서를 혼동'], ['심경 변화', '처음 마음 단서 → 사건 → 나중 마음 단서', '한쪽 마음만 보고 고르기'], ['원인 찾기', 'because, so 앞뒤 확인', '결과를 원인으로 고르기'], ['이어질 내용', '마지막 문장 + 인물의 생각', '이야기와 반대되는 행동 고르기']] },
      warn: '이어질 내용은 인물의 마지막 말이나 생각(He must be worried.)이 가장 큰 단서이다.' },
  ],
  bank: [
    { lv: 1, q: '시간 순서를 나타내는 신호어가 <b>아닌</b> 것은?', o: ['First', 'Then', 'Because', 'Finally'], a: 2, why: 'Because는 이유(원인)를 나타낸다. First, Then, Finally는 순서를 나타낸다.' },
    { lv: 1, q: '"Suddenly"의 뜻으로 알맞은 것은?', o: ['갑자기', '마침내', '먼저', '그러나'], a: 0, why: 'Suddenly는 "갑자기"라는 뜻으로 예상하지 못한 사건이 일어날 때 쓴다.' },
    { lv: 1, q: `다음 글에 나타난 'I'의 심정으로 알맞은 것은?<div class="passage">Before my speech, my hands were shaking, and my heart was beating fast.</div>`, o: ['bored', 'nervous', 'proud', 'sleepy'], a: 1, why: '발표 전에 손이 떨리고 심장이 빨리 뛰는 것은 긴장한(nervous) 마음이다.' },
    { lv: 2, q: `다음 문장을 일이 일어난 순서대로 배열한 것은?<div class="passage">(A) Then I put on my shoes.<br>(B) First, I washed my face.<br>(C) Finally, I left home for school.</div>`, o: ['(A)-(B)-(C)', '(B)-(C)-(A)', '(C)-(A)-(B)', '(B)-(A)-(C)'], a: 3, why: 'First(먼저) → Then(그다음) → Finally(마침내) 순서이므로 (B)-(A)-(C)이다.' },
    { lv: 2, q: `다음 글에서 Seho가 고양이를 수건으로 말린 <b>다음에</b> 한 일은?<div class="passage">🐱🌧️<br>On a rainy day, Seho found a small kitten under a car. It was wet and crying. He took it home and dried it with a towel. Then he gave it some warm milk. Soon the kitten fell asleep on his lap.</div>`, o: ['He gave it warm milk.', 'He found it under a car.', 'He took it to a vet.', 'He fell asleep.'], a: 0, why: '수건으로 말린 뒤 Then he gave it some warm milk라고 했다. 잠든 것은 고양이이고, 동물 병원 이야기는 없다.' },
    { lv: 2, q: `다음 글에 나타난 'I'의 심정으로 알맞은 것은?<div class="passage">🎹<br>I practiced the piano every day for the contest. But on the day of the contest, I made a mistake in the middle. I couldn't finish the song. When I came home, I went to my room and cried.</div>`, o: ['excited', 'thankful', 'relaxed', 'disappointed'], a: 3, why: '열심히 연습했지만 실수해서 곡을 끝내지 못하고 울었으므로 실망한(disappointed) 마음이다.' },
    { lv: 3, q: `다음 글에 나타난 Hajin의 심경 변화로 알맞은 것은?<div class="passage">🏫<br>It was Hajin's first day at his new school. When he walked into the classroom, everyone looked at him. He didn't know anyone, and he wanted to go home. Then a boy smiled and said, "Hi, I'm Woojin. Do you want to sit with me?" They talked about soccer during lunch. Hajin thought his new school might be fun.</div>`, o: ['nervous → glad', 'happy → sad', 'angry → bored', 'excited → scared'], a: 0, why: '처음에는 아는 사람이 없어 집에 가고 싶을 만큼 긴장했지만, 우진이 말을 걸어 준 뒤 학교가 재미있을 것 같다고 생각했다.' },
    { lv: 3, q: `다음 글의 내용을 일어난 순서대로 배열한 것은?<div class="passage">⛺🌠<br>Last Sunday, Mina's family went camping. When they arrived, Dad set up the tent. Mina and her brother collected some wood. In the evening, they cooked sausages over the fire. Later, they looked at the stars. Mina saw a shooting star and made a wish.</div>(a) 별 보기 (b) 텐트 치기 (c) 소시지 굽기 (d) 나무 모으기`, o: ['(d)-(b)-(c)-(a)', '(b)-(c)-(d)-(a)', '(b)-(d)-(c)-(a)', '(c)-(b)-(d)-(a)'], a: 2, why: '도착해서 텐트를 치고(b), 나무를 모으고(d), 저녁에 소시지를 굽고(c), 나중에 별을 보았다(a).' },
    { lv: 3, q: `다음 글에서 Jimin이 지각한 이유로 알맞은 것은?<div class="passage">⏰<br>Jimin was late for school today. Last night, she played a game on her phone until 1 a.m. So she didn't hear her alarm in the morning. Her teacher was not happy. Jimin decided to go to bed early from now on.</div>`, o: ['Her alarm was broken.', 'She missed the bus.', 'Her teacher called her.', 'She went to bed too late.'], a: 3, why: '새벽 1시까지 게임을 하느라 늦게 자서(원인) 알람을 듣지 못했다(결과). 알람이 고장 났다는 말은 없다.' },
    { lv: 4, q: `다음 글에 나타난 Yeon의 심경 변화로 가장 알맞은 것은?<div class="passage">⌚<br>For her birthday, Yeon got an old watch from her grandpa. At first, she didn't like it. "Everyone has a smartwatch," she thought. But one day, she found some small words on the back of the watch: "For my daughter, 1985." It was the watch Grandpa gave her mom long ago. Yeon held the watch tightly.</div>`, o: ['happy → angry', 'disappointed → touched', 'scared → excited', 'proud → bored'], a: 1, why: '처음에는 낡은 시계가 마음에 들지 않았지만(disappointed), 할아버지가 엄마에게 준 시계라는 것을 알고 꼭 쥐었다(touched).' },
    { lv: 4, q: `글의 흐름으로 보아, 다음 문장이 들어가기에 가장 알맞은 곳은?<div class="passage">Suddenly, he heard a sound behind him.<br><br>🐕 Tom was walking home from school. ( ① ) The street was quiet. ( ② ) A big dog came out from behind a tree and started to follow him. ( ③ ) Tom was scared and walked faster. ( ④ ) But when he got home, the dog just sat down and wagged its tail.</div>`, o: ['①', '②', '③', '④'], a: 1, why: '조용한 거리에서 갑자기 뒤에서 소리가 들렸고, 이어서 개가 나타났다는 흐름이므로 ②가 알맞다.' },
    { lv: 4, q: `주어진 문장 다음에 이어질 글의 순서로 알맞은 것은?<div class="passage">🥞 Junho wanted to make pancakes for his family.<br>(A) After that, he poured the mix into a hot pan and cooked it until it turned golden.<br>(B) First, he mixed flour, milk, and eggs in a big bowl.<br>(C) When the pancakes were ready, his family ate them with honey and said they were delicious.</div>`, o: ['(B)-(A)-(C)', '(A)-(C)-(B)', '(B)-(C)-(A)', '(C)-(A)-(B)'], a: 0, why: '먼저(First) 재료를 섞고(B), 그 후(After that) 팬에 굽고(A), 다 되자 가족이 먹었다(C).' },
    { lv: 5, q: `다음 글에서 Ms. Oh가 교실에 들어오기 <b>전에</b> 일어난 일이 <b>아닌</b> 것은?<div class="passage">🎈🎉<br>Dami's class planned a surprise party for their teacher, Ms. Oh, who was leaving the school. They decorated the classroom with balloons and wrote cards. When they heard footsteps, they turned off the lights and hid. The door opened, but it was the principal, not Ms. Oh! Everyone laughed. A few minutes later, Ms. Oh finally came in, and the students shouted, "Surprise!"</div>`, o: ['학생들이 풍선으로 교실을 꾸몄다.', '학생들이 불을 끄고 숨었다.', '학생들이 "Surprise!"라고 외쳤다.', '교장 선생님이 교실 문을 열었다.'], a: 2, why: '"Surprise!"는 몇 분 뒤 오 선생님이 마침내 들어왔을 때 외쳤다. 나머지는 모두 그 전에 일어난 일이다.' },
    { lv: 5, q: `다음 글에 나타난 Sunwoo의 심경 변화로 가장 알맞은 것은?<div class="passage">⚽<br>Sunwoo's team lost every game this season. Before the last game, nobody expected them to win. In the first half, the other team scored two goals. Sunwoo felt like giving up. But in the second half, his team scored three goals in a row. When the final whistle blew, Sunwoo jumped up and hugged his teammates.</div>`, o: ['calm → nervous', 'hopeless → delighted', 'proud → ashamed', 'excited → bored'], a: 1, why: '두 골을 먹고 포기하고 싶었지만(hopeless), 역전승 후 뛰어오르며 친구들을 껴안았다(delighted).' },
    { lv: 5, q: `다음 글 바로 뒤에 이어질 내용으로 가장 알맞은 것은?<div class="passage">👛<br>On her way home, Ara found a wallet on the street. There was some money and a student ID card inside. The name on the card was Lee Junsu, Hanbit Middle School. Ara's school was right next to Hanbit Middle School. "He must be worried," she thought.</div>`, o: ['Ara가 지갑의 돈으로 간식을 산다.', 'Ara가 지갑을 길에 다시 놓아 둔다.', 'Ara가 한빛중학교에 가서 지갑을 돌려준다.', 'Ara가 새 지갑을 사러 간다.'], a: 2, why: '지갑 주인의 학교가 아라의 학교 바로 옆이고, "그가 걱정하고 있겠다"고 생각했으므로 지갑을 돌려주러 갈 것이다.' },
  ],
});

ENG.add('m2', '독해: 제목과 요지', {
  sub: '주제문을 찾아 제목·요지로 바꾸기',
  kw: ['제목', '요지', '주제문', '두괄식·미괄식', 'However', 'should', '너무 넓은/좁은 보기', '비유적 제목'],
  sections: [
    { h: '주제·요지·제목의 차이',
      p: '세 가지 모두 글의 <b>중심 생각</b>을 묻지만 표현 방식이 다르다. <b>주제</b>는 "무엇에 관한 글인가", <b>요지</b>는 "글쓴이가 결국 하고 싶은 말(주장·교훈)", <b>제목</b>은 중심 생각을 짧고 눈에 띄게 줄인 것이다.',
      table: { head: ['구분', '형태', '예'], rows: [['주제', '명사구 (~의 중요성, ~하는 방법)', 'the benefits of taking the stairs'], ['요지', '완전한 문장 (~해야 한다, ~이다)', '계단을 이용하는 것은 손쉬운 건강 관리 방법이다.'], ['제목', '짧은 구·의문문·명령문·비유', 'Take the Stairs, Stay Healthy!']], cap: '주제·요지·제목 비교' },
      ex: [['Listening carefully shows that you care.', '주의 깊게 듣는 것은 네가 관심이 있다는 것을 보여 준다. (요지가 담긴 문장)'], ['Why Do Leaves Change Color in Fall?', '왜 가을에 잎의 색이 변할까? (의문문 제목)']] },
    { h: '주제문의 위치와 풀이 순서',
      p: '중2 수준의 글은 주제문이 <span class="hl">처음(두괄식)</span>, <span class="hl">끝(미괄식)</span>, 또는 <span class="hl">반전 신호어 뒤(중괄식)</span>에 온다. 예시나 경험담으로 시작하는 글은 끝부분에 요지가 나오는 경우가 많다.',
      table: { head: ['순서', '할 일', '단서'], rows: [['1', '첫 두 문장으로 화제 잡기', '질문(Have you ever ~?)이나 일반적인 생각'], ['2', '반전 신호어 뒤 확인', 'But, However, In fact'], ['3', '결론 신호어 확인', 'So, In short, That\'s why'], ['4', '주장 표현 확인', 'should, must, It is important to'], ['5', '보기를 중심 생각과 비교', '너무 넓은·좁은 보기 지우기']], cap: '제목·요지 풀이 순서' },
      ex: [['Some people think ~. However, ~.', '어떤 사람들은 ~라고 생각한다. 하지만 ~. (However 뒤가 요지)'], ['Small daily habits can make a big difference.', '작은 일상 습관이 큰 차이를 만들 수 있다. (마지막 문장 = 요지)']],
      tip: '"Some people think ~"로 시작하면 글쓴이는 대개 그 생각에 반대하는 말을 뒤에서 한다.' },
    { h: '요지를 알려 주는 신호어',
      p: '요지는 글쓴이의 <b>생각·주장·교훈</b>이므로 의견을 나타내는 표현과 함께 나오는 경우가 많다.',
      table: { head: ['신호어', '뜻', '쓰임'], rows: [['However / But / In fact', '그러나 / 사실은', '앞의 통념을 뒤집고 진짜 생각 제시'], ['So / Therefore', '그래서 / 따라서', '결론'], ['should / must / need to', '~해야 한다', '주장'], ['It is important to ~', '~하는 것이 중요하다', '주장'], ['Remember that ~ / Try ~', '~을 기억하라 / ~해 보라', '명령문으로 된 요지']] },
      ex: [['Remember that there is a real person behind the screen.', '화면 너머에 실제 사람이 있다는 것을 기억하라.'], ['So when you study, put your phone in another room.', '그러니 공부할 때는 휴대 전화를 다른 방에 두어라.']] },
    { h: '오답 함정',
      p: '제목·요지 문제의 오답은 <b>글의 일부</b>만 다루거나, 글보다 <b>너무 넓거나</b>, 글과 <b>반대</b>인 내용으로 만든다.',
      table: { head: ['함정', '예 (동물의 겨울나기 글)', '판단'], rows: [['너무 넓음', 'Animals of the World', '글은 "겨울나기"만 다룬다'], ['너무 좁음', 'Why Bears Sleep So Much', '곰은 예시 중 하나'], ['반대 내용', '게임은 시간 낭비일 뿐이다', '글쓴이가 반박하는 생각'], ['글에 없음', 'The Best Places to See Animals', '글에 근거가 없다']], cap: '제목·요지 오답 유형' },
      warn: '글에 나온 낱말이 많이 들어 있다고 정답이 아니다. 예시 하나만 담은 보기는 "너무 좁은" 보기이다.' },
  ],
  bank: [
    { lv: 1, q: '"요지"의 뜻으로 알맞은 것은?', o: ['글에 나온 가장 어려운 단어', '글쓴이가 전하려는 핵심 생각', '글의 첫 번째 문장', '글에 나온 예시'], a: 1, why: '요지는 글쓴이가 결국 하고 싶은 말(주장·교훈)이다. 첫 문장이 항상 요지인 것은 아니다.' },
    { lv: 1, q: '요지를 찾는 신호어로 보기 <b>어려운</b> 것은?', o: ['However', 'We should', 'For example', 'It is important to'], a: 2, why: 'For example 뒤에는 요지를 뒷받침하는 예시가 온다. 나머지는 글쓴이의 생각을 드러낸다.' },
    { lv: 1, q: `다음 글의 제목으로 알맞은 것은?<div class="passage">📚✨<br>Reading books helps you learn new words. It also lets you travel to other worlds in your mind. Through stories, you can meet many different people and understand their feelings.</div>`, o: ['How to Write a Diary', 'Travel Tips for Teens', 'New Words in Science', 'The Magic of Reading'], a: 3, why: '독서가 주는 좋은 점(새 단어, 상상 여행, 다른 사람 이해)을 말하는 글이다.' },
    { lv: 2, q: `다음 글의 요지로 가장 알맞은 것은?<div class="passage">🏢🚶<br>Many people take the elevator even when they go up only one or two floors. But taking the stairs is a simple way to stay healthy. It makes your legs and heart stronger, and it doesn't cost any money. You don't need to go to a gym to exercise. Just choose the stairs instead of the elevator every day.</div>`, o: ['엘리베이터는 고장이 잦다.', '계단을 이용하는 것은 손쉬운 건강 관리 방법이다.', '헬스장에서 운동해야 효과가 있다.', '다리 근육은 심장보다 중요하다.'], a: 1, why: 'But 뒤에서 계단 이용이 건강을 지키는 간단한 방법이라고 하고, 마지막에 계단을 이용하라고 권한다. ③은 글과 반대이다.' },
    { lv: 2, q: `다음 글의 제목으로 가장 알맞은 것은?<div class="passage">👂💬<br>When your friend tells you about a problem, what do you do? Many people start giving advice right away. However, sometimes your friend just wants someone to listen. Look at your friend's eyes, nod your head, and don't check your phone. Listening carefully shows that you care. Often, that is the best help you can give.</div>`, o: ['Why Friends Fight', 'Good Advice for Every Problem', 'How to Use Your Phone Wisely', 'Listening: The Best Way to Help a Friend'], a: 3, why: 'However 뒤에서 친구는 들어 주기를 원할 때가 있다고 하고, 잘 듣는 것이 가장 좋은 도움이라고 정리한다. ②는 글이 반대하는 행동이다.' },
    { lv: 2, q: `다음 글의 요지로 가장 알맞은 것은?<div class="passage">✏️❌<br>Nobody likes making mistakes. We feel embarrassed when we give a wrong answer in class. But mistakes are a natural part of learning. When you make a mistake, you find out what you don't know yet. Then you can practice that part more. So don't be afraid of mistakes. They are steps to getting better.</div>`, o: ['실수를 두려워하지 말고 배움의 기회로 삼아야 한다.', '수업 시간에는 정답만 말해야 한다.', '틀린 문제는 다시 풀 필요가 없다.', '친구의 실수를 지적해 주어야 한다.'], a: 0, why: 'But 뒤에서 실수는 배움의 일부라고 하고, So don\'t be afraid of mistakes로 요지를 밝힌다.' },
    { lv: 3, q: `다음 글의 요지로 가장 알맞은 것은?<div class="passage">🧹⏰<br>Jisu's room was always messy. She often couldn't find her homework or her bus card in the morning, so she was late a lot. One day, she decided to spend just ten minutes every night putting things in their places. After a month, her mornings became calm, and she was never late. Small daily habits can make a big difference in your life.</div>`, o: ['아침에는 버스를 일찍 타야 한다.', '방 청소는 주말에 몰아서 하는 것이 좋다.', '작은 일상 습관이 삶에 큰 변화를 가져온다.', '지수는 숙제를 자주 잊어버린다.'], a: 2, why: '지수의 경험을 예로 든 뒤 마지막 문장(미괄식)에서 작은 습관이 큰 차이를 만든다는 요지를 밝힌다. ④는 세부 내용일 뿐이다.' },
    { lv: 3, q: `다음 글의 제목으로 가장 알맞은 것은?<div class="passage">🍁🍂<br>In spring and summer, leaves are green because they have a lot of chlorophyll. Chlorophyll helps trees make food from sunlight. In fall, the days get shorter and colder, so trees stop making food. The green color slowly disappears, and the yellow and orange colors that were hiding in the leaves appear. Some leaves also make new red colors in the fall.</div>`, o: ['Why Do Leaves Change Color in Fall?', 'How Trees Drink Water', 'The Best Places to See Fall Leaves', 'Trees That Stay Green All Year'], a: 0, why: '잎이 초록색인 이유와 가을에 노랑·주황·빨강으로 변하는 이유를 설명하는 글이다.' },
    { lv: 3, q: `다음 글의 요지로 가장 알맞은 것은?<div class="passage">📱📖<br>Many students study with their phones next to them. They answer messages, watch short videos, and then go back to their books. They think they can do two things at once. However, our brains can focus well on only one thing at a time. Every time you check your phone, it takes time to focus on studying again. So when you study, put your phone in another room.</div>`, o: ['짧은 영상은 공부에 도움이 된다.', '메시지에는 바로 답해야 한다.', '두 가지 일을 동시에 하는 연습이 필요하다.', '공부할 때는 휴대 전화를 멀리 두고 한 가지에 집중해야 한다.'], a: 3, why: 'However 뒤에서 뇌는 한 번에 한 가지에만 잘 집중한다고 하고, So 뒤에서 휴대 전화를 다른 방에 두라고 한다.' },
    { lv: 4, q: `다음 글의 제목으로 가장 알맞은 것은?<div class="passage">🥬🌶️<br>Every November, many Korean families get together to make kimchi for the winter. This event is called gimjang. Family members and neighbors wash cabbages, mix the spicy sauce, and share the work. It takes a whole day, but nobody does it alone. After the work, they eat boiled pork with fresh kimchi and talk for hours. Gimjang is not just about making food. It is a time for sharing and bringing people closer.</div>`, o: ['How to Grow Cabbage', 'The Spiciest Foods in Korea', 'Gimjang: More Than Making Kimchi', 'Why Pork Is Healthy'], a: 2, why: '마지막 두 문장에서 김장은 음식을 만드는 것만이 아니라 나누고 가까워지는 시간이라고 정리한다.' },
    { lv: 4, q: `다음 글의 요지로 가장 알맞은 것은?<div class="passage">💻💬<br>On the internet, people sometimes write things they would never say face to face. Because they can't see the other person, they forget that a real person will read their words. A short, mean comment can hurt someone for a long time. Before you post a comment, ask yourself, "Would I say this to the person's face?" If the answer is no, don't post it. Remember that there is always a real person behind the screen.</div>`, o: ['온라인에서도 상대를 배려하며 말해야 한다.', '인터넷 댓글은 짧을수록 좋다.', '얼굴을 보고 말하는 것은 어렵다.', '인터넷 사용 시간을 줄여야 한다.'], a: 0, why: '댓글을 쓰기 전에 직접 얼굴을 보고도 할 말인지 생각하라고 하며, 화면 너머에 실제 사람이 있음을 기억하라고 한다.' },
    { lv: 4, q: `다음 글의 제목으로 가장 알맞은 것은?<div class="passage">🥱💡<br>These days, we rarely feel bored. Whenever we have a free minute, we pick up our phones. But being bored is not always bad. In fact, boredom can be good for our brains. When we have nothing to do, our minds start to wander, and we come up with new ideas. Many artists and writers say their best ideas came while they were doing nothing. So next time you feel bored, don't reach for your phone right away.</div>`, o: ['Phones Make Us Smarter', 'The Surprising Benefits of Boredom', 'Famous Artists and Their Works', 'How to Stay Busy All Day'], a: 1, why: 'But, In fact 뒤에서 지루함이 뇌에 좋고 새로운 생각을 떠올리게 한다고 말한다. ③은 예시의 일부, ④는 반대 내용이다.' },
    { lv: 5, q: `다음 글의 요지로 가장 알맞은 것은?<div class="passage">👔🏫<br>Some people say students should be allowed to wear whatever they want to school. They believe clothes help students show who they are. I understand this idea, but I think school uniforms have more good points. First, students don't have to worry about what to wear every morning. Second, families can save money because they don't need to buy many trendy clothes. Most of all, uniforms help students feel that they belong to one community. Uniforms make school life simpler and fairer.</div>`, o: ['학생들은 원하는 옷을 입을 수 있어야 한다.', '교복은 장점이 많으므로 입는 것이 바람직하다.', '교복은 비싸므로 가격을 낮춰야 한다.', '유행하는 옷은 개성을 보여 준다.'], a: 1, why: '앞부분은 남의 의견이고, but I think 뒤에서 교복의 장점을 나열하며 교복이 학교생활을 더 간단하고 공정하게 만든다고 주장한다. ①, ④는 글쓴이가 반박하는 생각이다.' },
    { lv: 5, q: `다음 글의 제목으로 가장 알맞은 것은?<div class="passage">⏱️🧺<br>Do you often put off small tasks? Washing a cup, answering a message, or hanging up your coat takes only a minute or two. But when you put these tasks off, they pile up, and soon you have a mountain of work. Try this simple rule: if something takes less than two minutes, do it right away. You'll be surprised at how much cleaner your room and your mind become. Small tasks are easy to finish but hard to catch up on.</div>`, o: ['Why We Need More Free Time', 'How to Clean a Mountain', 'Answering Messages Politely', 'The Two-Minute Rule: Do It Now'], a: 3, why: '2분 안에 끝나는 일은 바로 하라는 규칙을 소개하는 글이다. ②의 mountain은 일이 쌓인 것을 비유한 말일 뿐이다.' },
    { lv: 5, q: `다음 글의 제목으로 가장 알맞은 것은?<div class="passage">🐻🐿️🐦❄️<br>When winter comes, food becomes hard to find, so animals have different ways to survive. Some birds fly thousands of kilometers to warmer places. Bears eat a lot in the fall and sleep through most of the winter. Squirrels hide nuts in many places and dig them up when they are hungry. Even small insects find shelter under tree bark or underground. Each animal has its own way to get through the cold season.</div>`, o: ['Animals of the World', 'Why Bears Sleep So Much', 'How Animals Get Through Winter', 'Birds That Fly the Farthest'], a: 2, why: '첫 문장과 마지막 문장에서 동물마다 겨울을 나는 방법이 다르다고 말한다. ①은 너무 넓고, ②와 ④는 예시 하나만 다룬 좁은 제목이다.' },
  ],
});

ENG.add('m2', '독해: 가리키는 대상 찾기', {
  sub: '대명사·지시어가 가리키는 말을 앞에서 찾기',
  kw: ['대명사', '지시어', 'it / they', 'this / these', 'one', '수·성 일치', '대입해 보기', '나머지와 다른 것'],
  sections: [
    { h: '대명사와 지시어',
      p: '영어는 같은 말을 되풀이하지 않으려고 <b>대명사</b>(he, she, it, they)와 <b>지시어</b>(this, that, these, those)를 쓴다. 이 말들이 가리키는 대상은 대부분 <span class="hl">바로 앞 문장이나 앞부분</span>에 있다.',
      table: { head: ['대명사·지시어', '가리키는 것', '찾는 방법'], rows: [['he / him / his', '남자 한 명', '앞에 나온 남자 인물'], ['she / her', '여자 한 명', '앞에 나온 여자 인물'], ['it / its', '단수인 사물·동물, 앞 문장 내용', '앞의 단수 명사'], ['they / them', '복수인 사람·사물', '앞의 복수 명사, A and B'], ['this / that', '앞 문장 전체의 내용', '앞 문장을 우리말로 요약'], ['one', '같은 종류의 다른 것', 'a new one = 새 ○○']], cap: '대명사·지시어가 가리키는 것' },
      ex: [['I have a new bike. It is red.', '나는 새 자전거가 있다. 그것(자전거)은 빨간색이다.'], ['Mina and Jisu live near my house. They are my friends.', '미나와 지수는 우리 집 근처에 산다. 그들은 내 친구이다.']] },
    { h: '대상 찾기 풀이 순서',
      p: '밑줄 친 말이 나오면 <b>앞쪽으로 거슬러 올라가며</b> 후보를 찾고, 후보를 밑줄 자리에 넣어 뜻이 통하는지 확인한다.',
      table: { head: ['순서', '할 일', '확인할 점'], rows: [['1', '밑줄 친 말의 수·성 확인', 'it(단수) / they(복수) / he(남) / she(여)'], ['2', '앞 문장에서 후보 찾기', '조건에 맞는 명사를 모두 표시'], ['3', '후보를 대입해 읽기', '"그 후보가 ~했다"가 말이 되는가'], ['4', '동사와 어울리는지 확인', 'sat by the bowl → 고양이, 물고기 ×'], ['5', '여러 개면 하나씩 표시', '①~④가 각각 누구인지 적기']], cap: '가리키는 대상 찾기 5단계' },
      ex: [['Her cats watched the fish. They sat by the bowl.', '그녀의 고양이들은 물고기를 지켜보았다. 그들(고양이들)은 어항 옆에 앉아 있었다.']],
      tip: '복수 명사가 여러 개 있으면 동사가 무엇을 하는지 보고 판단한다. 물고기는 어항 옆에 "앉을" 수 없다.' },
    { h: 'this·these·one이 가리키는 것',
      p: '<span class="hl">this, that</span>은 앞에 나온 <b>문장 전체의 내용</b>을 가리킬 때가 많다. <b>this problem, this rule</b>처럼 명사와 함께 쓰면 앞에서 말한 문제나 규칙을 가리킨다. <b>one</b>은 앞에 나온 명사와 <b>같은 종류의 다른 것</b>이고, it은 <b>바로 그것</b>이다.',
      table: { head: ['표현', '예', '가리키는 것'], rows: [['this (문장 내용)', 'Junho forgot her birthday. This made her sad.', '준호가 생일을 잊은 것'], ['this problem', 'A lot of food is wasted. To solve this problem, ~', '음식이 많이 버려지는 것'], ['these + 명사', 'Cactuses need little water. These plants ~', '물이 적어도 사는 식물'], ['one / it', 'I lost my umbrella, so I need a new one. / I found it!', '새 우산 / 잃어버린 그 우산']] },
      ex: [['I lost my umbrella, so I need to buy a new one.', '나는 우산을 잃어버려서 새것을 하나 사야 한다. (one = 우산)']] },
    { h: '나머지와 다른 것 찾기',
      p: '"가리키는 대상이 나머지 넷과 다른 것은?" 문제는 인물이 두 명 이상 나온다. 같은 he, she라도 문장마다 가리키는 사람이 바뀌므로 <b>밑줄마다 누구인지 적어 두고</b> 비교한다.',
      table: { head: ['자주 하는 실수', '예', '바른 방법'], rows: [['가장 가까운 명사만 고름', 'Dohyun held his hand. → Dohyun?', '내용상 동생의 손을 잡은 것'], ['문장의 주어만 봄', 'Ms. Choi ~. She offered to teach.', '가르쳐 준 사람은 선생님'], ['사물과 동물 혼동', 'The book had tips. It ~', '책 ↔ 강아지 구분'], ['앞 문장 내용을 놓침', 'This made her sad.', '명사 하나가 아니라 사건 전체']] },
      warn: '대명사는 "가장 가까운 명사"가 아니라 "뜻이 통하는 명사"를 가리킨다.' },
  ],
  bank: [
    { lv: 1, q: `밑줄 친 It이 가리키는 것은?<div class="passage">I have a new bike. <u>It</u> is red.</div>`, o: ['I', 'red', 'a new bike', 'new'], a: 2, why: '앞 문장의 단수 사물 a new bike를 가리킨다.' },
    { lv: 1, q: `밑줄 친 They가 가리키는 것은?<div class="passage">Mina and Jisu are in my class. <u>They</u> live near my house.</div>`, o: ['Mina and Jisu', 'my class', 'my house', 'Mina'], a: 0, why: 'They는 복수이므로 Mina and Jisu 두 사람을 가리킨다.' },
    { lv: 1, q: `밑줄 친 one이 가리키는 것은?<div class="passage">I lost my umbrella, so I need to buy a new <u>one</u>.</div>`, o: ['a friend', 'a store', 'some money', 'an umbrella'], a: 3, why: 'one은 앞에 나온 명사와 같은 종류의 것을 가리키므로 새 우산(an umbrella)이다.' },
    { lv: 2, q: `밑줄 친 them이 가리키는 것은?<div class="passage">🍅🌶️🥒<br>My grandmother has a small garden behind her house. She grows tomatoes, peppers, and cucumbers there. Every summer, she picks <u>them</u> and gives some to our neighbors. They always thank her with a smile.</div>`, o: ['her neighbors', 'tomatoes, peppers, and cucumbers', 'her house and garden', 'our family'], a: 1, why: '할머니가 따는(pick) 것은 앞에서 기른다고 한 토마토, 고추, 오이이다.' },
    { lv: 2, q: `밑줄 친 This가 가리키는 내용은?<div class="passage">🎂📅<br>Junho forgot his mom's birthday last year. <u>This</u> made her a little sad. So this year, he wrote the date on his calendar in red and bought her flowers.</div>`, o: ['준호가 달력을 산 것', '엄마가 슬퍼한 것', '준호가 날짜를 빨간색으로 쓴 것', '준호가 작년에 엄마 생일을 잊어버린 것'], a: 3, why: 'This는 앞 문장 전체, 즉 준호가 작년에 엄마 생일을 잊어버린 일을 가리킨다. 그 일 때문에 엄마가 슬펐다.' },
    { lv: 2, q: `밑줄 친 He가 가리키는 사람은?<div class="passage">📐<br>Yuna asked her brother Minsu to help with her math homework. <u>He</u> was busy, but he sat down next to her and explained the problems one by one. Thanks to him, Yuna finished her homework before dinner.</div>`, o: ['Yuna', "Yuna's dad", 'Minsu', 'the math teacher'], a: 2, why: 'He는 남자 한 명이고, 숙제를 도와 달라는 부탁을 받은 오빠(형) 민수이다.' },
    { lv: 3, q: `밑줄 친 it이 가리키는 것은?<div class="passage">🐢<br>Sejin's class has a turtle named Ddukbae. The students take turns feeding <u>it</u> every morning. Last week, Sejin forgot to close the tank, and the turtle went out. The whole class looked for it, and finally they found it under the teacher's desk.</div>`, o: ['the turtle', 'the class', 'the tank', 'the desk'], a: 0, why: '학생들이 돌아가며 먹이를 주는(feed) 것은 거북이 뚝배기이다.' },
    { lv: 3, q: `밑줄 친 These plants가 가리키는 것은?<div class="passage">🌵<br>Most plants need water every few days. However, some plants, like cactuses, can live with very little water. <u>These plants</u> are good for busy people because they don't need much care. You only have to water them once or twice a month.</div>`, o: ['물을 자주 주어야 하는 식물', '선인장처럼 물이 적어도 사는 식물', '바쁜 사람들이 키우는 모든 식물', '한 달에 한 번 사는 식물'], a: 1, why: '바로 앞 문장의 "선인장처럼 아주 적은 물로도 사는 식물"을 가리킨다.' },
    { lv: 3, q: `밑줄 친 They가 가리키는 것은?<div class="passage">🐠🐈<br>Hyemin's parents bought her two goldfish for her birthday. She put the fish in a glass bowl on the table. At first, her cats watched the fish all day. <u>They</u> sat by the bowl and moved their tails slowly. Hyemin was worried, so she moved the bowl to a high shelf.</div>`, o: ["Hyemin's parents", 'the goldfish', "Hyemin's cats", 'Hyemin and her parents'], a: 2, why: '어항 옆에 앉아 꼬리를 천천히 흔든 것은 물고기를 지켜보던 고양이들이다. 물고기는 어항 옆에 앉을 수 없다.' },
    { lv: 4, q: `밑줄 친 부분이 가리키는 대상이 나머지 셋과 <b>다른</b> 것은?<div class="passage">🐕📘<br>My family adopted a puppy from an animal shelter last month. ① <u>It</u> was very shy at first and hid under the sofa. We made a soft bed for ② <u>it</u> next to my desk. The shelter also gave us a small book about caring for dogs. ③ <u>It</u> had many useful tips. Now our puppy follows me everywhere, and ④ <u>it</u> sleeps in its bed every night.</div>`, o: ['①', '②', '③', '④'], a: 2, why: '①, ②, ④는 강아지(puppy)이고, 유용한 조언이 들어 있는 ③은 보호소에서 받은 책(book)이다.' },
    { lv: 4, q: `밑줄 친 this problem이 가리키는 내용은?<div class="passage">🍌🗑️<br>Many people throw away food that is a little old, even when it is still safe to eat. Stores also throw away fruits and vegetables that don't look perfect. Because of this, a lot of food is wasted every day. To solve <u>this problem</u>, some stores now sell "ugly" fruits and vegetables at lower prices. Some apps also help people share extra food with their neighbors.</div>`, o: ['많은 음식이 버려지는 것', '가게가 과일을 비싸게 파는 것', '못생긴 과일이 맛이 없는 것', '이웃과 음식을 나누는 것'], a: 0, why: '바로 앞의 "매일 많은 음식이 버려진다"는 문제를 가리킨다. ④는 문제를 해결하는 방법이다.' },
    { lv: 4, q: `밑줄 친 it이 가리키는 것으로 가장 알맞은 것은?<div class="passage">🍽️📵<br>Our school started a new rule this year: no phones during lunchtime. At first, many students didn't like <u>it</u>. They wanted to watch videos while eating. But after a few weeks, something changed. Students began to talk and laugh more at the lunch table. Some even started playing board games together. Now most students say the rule made lunchtime more fun.</div>`, o: ['점심시간에 휴대 전화를 쓰지 않는 규칙', '점심시간', '보드게임', '영상 시청'], a: 0, why: '학생들이 처음에 싫어한 것은 올해 새로 생긴 규칙(점심시간 휴대 전화 금지)이다. 마지막 문장의 the rule도 같은 대상이다.' },
    { lv: 5, q: `밑줄 친 부분이 가리키는 대상이 나머지 셋과 <b>다른</b> 것은?<div class="passage">🏖️<br>Dohyun went to the beach with his little brother, Jaemin. Jaemin was only five, so Dohyun held ① <u>his</u> small hand all the time. When they built a sand castle, ② <u>he</u> asked Dohyun to make a tall tower. Dohyun made it, and Jaemin clapped ③ <u>his</u> hands happily. On the way home, ④ <u>he</u> carried Jaemin on his back because the little boy was tired.</div>`, o: ['①', '②', '③', '④'], a: 3, why: '①은 다섯 살 동생 재민의 손, ②는 탑을 만들어 달라고 한 재민, ③은 손뼉을 친 재민이다. ④는 피곤한 동생을 업어 준 도현이다.' },
    { lv: 5, q: `밑줄 친 부분이 가리키는 대상이 나머지 셋과 <b>다른</b> 것은?<div class="passage">🎻<br>Seoyeon wanted to join the school orchestra, but she couldn't read music well. Her music teacher, Ms. Choi, noticed this. ① <u>She</u> offered to teach Seoyeon after school twice a week. Seoyeon practiced hard, and ② <u>she</u> soon learned how to read notes. At the audition, ③ <u>she</u> played the violin without a single mistake. After the audition, ④ <u>she</u> ran to Ms. Choi and thanked her.</div>`, o: ['①', '②', '③', '④'], a: 0, why: '①은 방과 후에 가르쳐 주겠다고 한 최 선생님이고, ②~④는 모두 서연이다.' },
    { lv: 5, q: `밑줄 친 (A), (B)가 가리키는 것을 바르게 짝지은 것은?<div class="passage">🍢🌶️<br>Amy is from Canada, and she came to Korea last month as an exchange student. Last Saturday, she visited a traditional market in Seoul for the first time with her host sister, Jiwon. There were many kinds of food, but (A) <u>one</u> caught her eye: tteokbokki. The seller gave her some in a small paper cup to try. (B) <u>It</u> was so spicy that her face turned red, but she smiled and asked for more.</div>`, o: ['(A) 시장 – (B) 종이컵', '(A) 판매자 – (B) 떡볶이', '(A) 떡볶이 – (B) 종이컵', '(A) 떡볶이 – (B) 떡볶이'], a: 3, why: '(A) one은 여러 음식 중 하나인 떡볶이이고, (B) 너무 매워 얼굴이 빨개지게 한 것도 맛본 떡볶이이다. 종이컵은 매울 수 없다.' },
  ],
});

ENG.add('m2', '독해: 글의 순서와 이어질 내용', {
  sub: '연결 고리로 순서 잇기, 문장 넣기, 다음 내용 예측',
  kw: ['글의 순서', '주어진 문장 넣기', '이어질 내용', 'a → the', '대명사 단서', '연결어', '흐름 끊김'],
  sections: [
    { h: '순서를 알려 주는 연결 고리',
      p: '글의 문장들은 <b>연결 고리</b>로 이어져 있다. 순서 배열 문제는 각 단락의 첫 문장에 있는 연결 고리를 찾아 <span class="hl">앞에 무엇이 와야 하는지</span> 생각하면 풀린다.',
      table: { head: ['연결 고리', '예', '알 수 있는 것'], rows: [['대명사', 'They eat only leaves. / He wanted ~', '가리키는 대상이 앞에 나와 있어야 한다'], ['지시어 + 명사', 'these leaves, this problem', '그 잎·문제가 앞에서 소개되어야 한다'], ['관사 a → the', 'a cake ~ The cake ~', '처음엔 a, 다시 말할 땐 the'], ['연결어', 'However, So, For example', '앞 내용과 반대·결과·예시 관계'], ['시간 표현', 'First, Then, Finally', '일이 일어난 순서']], cap: '순서 배열의 단서' },
      ex: [['I bought a cake yesterday. The cake was delicious.', '나는 어제 케이크를 하나 샀다. 그 케이크는 맛있었다.'], ['They eat almost nothing but eucalyptus leaves. Because these leaves ~', '그들은 거의 유칼립투스 잎만 먹는다. 이 잎들은 ~ 때문에']] },
    { h: '순서 배열 풀이 순서',
      p: '(A), (B), (C)를 하나씩 해석하기보다 <b>첫 문장의 단서</b>를 먼저 보고, 주어진 글 바로 다음에 올 수 있는 것을 고른다.',
      table: { head: ['순서', '할 일', '확인할 점'], rows: [['1', '주어진 글의 화제와 마지막 문장 확인', '무엇이 처음 소개되었는가'], ['2', '(A)(B)(C) 첫 문장의 단서 표시', '대명사, the, 연결어'], ['3', '주어진 글 다음에 올 단락 고르기', '새 대상이 처음 나오는 단락'], ['4', '나머지 둘의 순서 정하기', 'However, So, Finally는 뒤쪽'], ['5', '처음부터 이어 읽어 확인', '흐름이 자연스러운가']], cap: '순서 배열 5단계' },
      tip: 'He, They, this, the로 시작하는 단락은 그것을 소개한 단락보다 앞에 올 수 없다.' },
    { h: '주어진 문장 넣기',
      p: '주어진 문장이 들어갈 곳은 <span class="hl">흐름이 끊기는 곳</span>이다. 앞 문장과 뒤 문장이 잘 이어지지 않는 자리를 찾고, 주어진 문장의 단서(대명사, 연결어)가 앞뒤와 맞는지 확인한다.',
      table: { head: ['주어진 문장의 단서', '앞에 와야 할 내용', '뒤에 올 내용'], rows: [['But it was locked.', '문을 열려고 한 것', '열쇠를 찾음'], ['However, it was too big ~', '마음에 드는 물건을 찾음', '배달을 부탁함'], ['So how do they ~?', '어려움·문제 제시', '그 방법 설명'], ['Because of this, ~', '원인이 되는 사건', '결과 이후의 이야기']] },
      ex: [['She tried to open the door. But it was locked.', '그녀는 문을 열려고 했다. 그러나 문은 잠겨 있었다.']],
      warn: '주어진 문장을 넣었을 때 뒤 문장과도 이어져야 한다. 앞만 맞는 자리는 함정이다.' },
    { h: '이어질 내용 예측',
      p: '글 다음에 이어질 내용은 <b>마지막 한두 문장</b>이 예고한다. "Here are some ~", "Let\'s look at ~", "So what can we do?" 같은 말 뒤에는 그 내용이 바로 이어진다.',
      table: { head: ['마지막 문장', '이어질 내용'], rows: [['Here are some simple things you can do.', '실천 방법'], ["Let's look at why ~.", '그 이유 설명'], ['Here are the details.', '앞에서 말한 행사의 세부 내용'], ['I will tell you about ~.', '그 주제의 소개']] },
      ex: [['So what can we do? Here are some tips.', '그러면 우리는 무엇을 할 수 있을까? 여기 몇 가지 조언이 있다.']] },
  ],
  bank: [
    { lv: 1, q: '빈칸에 알맞은 말을 순서대로 고른 것은?<div class="passage">I bought ___ cake yesterday. ___ cake was delicious.</div>', o: ['the – A', 'a – The', 'a – A', 'the – The'], a: 1, why: '처음 소개할 때는 a, 앞에서 말한 것을 다시 가리킬 때는 the를 쓴다.' },
    { lv: 1, q: '글의 순서를 정하는 단서로 보기 <b>어려운</b> 것은?', o: ['대명사 (it, they)', '연결어 (However, So)', '시간 표현 (Then, Later)', '문장의 길이'], a: 3, why: '문장의 길이는 순서와 관계없다. 대명사, 연결어, 시간 표현이 순서의 단서가 된다.' },
    { lv: 1, q: `다음 문장을 순서대로 배열한 것은?<div class="passage">(A) After that, I brushed my teeth.<br>(B) I woke up at seven.<br>(C) Then I ate breakfast.</div>`, o: ['(A)-(B)-(C)', '(B)-(A)-(C)', '(B)-(C)-(A)', '(C)-(B)-(A)'], a: 2, why: '일어나서(B) → 그다음 아침을 먹고(C) → 그 후에 이를 닦았다(A).' },
    { lv: 2, q: `주어진 글 다음에 이어질 글의 순서로 알맞은 것은?<div class="passage">🐦🏠 Last weekend, I made a birdhouse with my dad.<br>(A) Then we painted it blue and yellow.<br>(B) First, we cut some pieces of wood and put them together with nails.<br>(C) Finally, we hung it on the tree in our yard. A few days later, a little bird came to live in it.</div>`, o: ['(B)-(A)-(C)', '(A)-(C)-(B)', '(B)-(C)-(A)', '(C)-(A)-(B)'], a: 0, why: 'First(나무 자르고 조립) → Then(색칠) → Finally(나무에 걸기) 순서이다.' },
    { lv: 2, q: `다음 글 바로 뒤에 이어질 내용으로 알맞은 것은?<div class="passage">🎪📢<br>Dear students, many of you have asked about this year's school festival. It will be held on October 25 and 26. We have prepared some special events that you have never seen before. In this letter, I will tell you about these special events.</div>`, o: ['올해 축제의 특별 행사 소개', '작년 축제의 문제점', '학교 급식 메뉴', '학생들의 시험 일정'], a: 0, why: '마지막 문장 I will tell you about these special events에서 다음에 특별 행사를 소개할 것임을 알 수 있다.' },
    { lv: 2, q: `글의 흐름으로 보아, 다음 문장이 들어가기에 가장 알맞은 곳은?<div class="passage">But it was locked.<br><br>🚪🔑 Hana came home from school. ( ① ) She tried to open the front door. ( ② ) She looked for her key in her bag, but it wasn't there. ( ③ ) So she called her mom. ( ④ ) Her mom said she would be home in ten minutes.</div>`, o: ['①', '②', '③', '④'], a: 1, why: '문을 열려고 했지만(②의 앞) 잠겨 있어서 열쇠를 찾았다(②의 뒤)는 흐름이므로 ②가 알맞다.' },
    { lv: 3, q: `주어진 글 다음에 이어질 글의 순서로 알맞은 것은?<div class="passage">🐨 Koalas live in Australia and spend most of their time in trees.<br>(A) Because these leaves don't give them much energy, koalas sleep up to 20 hours a day.<br>(B) They eat almost nothing but eucalyptus leaves.<br>(C) So when you see a koala, it is probably sleeping!</div>`, o: ['(A)-(B)-(C)', '(B)-(C)-(A)', '(C)-(A)-(B)', '(B)-(A)-(C)'], a: 3, why: '(B)에서 유칼립투스 잎을 소개해야 (A)의 these leaves가 가리킬 대상이 생긴다. (A)의 오래 잔다는 내용의 결과가 (C)의 So이다.' },
    { lv: 3, q: `글의 흐름으로 보아, 다음 문장이 들어가기에 가장 알맞은 곳은?<div class="passage">However, it was too big to carry home in their car.<br><br>🪑 Minseo wanted a new desk for her room. ( ① ) On Saturday, she went to a furniture store with her dad. ( ② ) She found a perfect white desk with three drawers. ( ③ ) So they asked the store to deliver it the next day. ( ④ ) Now Minseo studies at her new desk every evening.</div>`, o: ['①', '②', '③', '④'], a: 2, why: '마음에 드는 책상을 찾았지만(③의 앞) 너무 커서 차로 옮길 수 없었고, 그래서 배달을 부탁했다(③의 뒤).' },
    { lv: 3, q: `다음 글 바로 뒤에 이어질 내용으로 가장 알맞은 것은?<div class="passage">🛍️🌊<br>Plastic bags are cheap and useful, but they cause big problems. They take hundreds of years to break down, and many of them end up in the ocean. Sea animals often think they are food and eat them. So what can we do? Here are some simple things you can do every day.</div>`, o: ['일상에서 비닐봉지 사용을 줄이는 방법', '비닐봉지를 만드는 과정', '바다 동물의 종류', '비닐봉지의 역사'], a: 0, why: 'So what can we do? Here are some simple things you can do every day 다음에는 일상에서 실천할 방법이 이어진다.' },
    { lv: 4, q: `주어진 글 다음에 이어질 글의 순서로 가장 알맞은 것은?<div class="passage">🥱 Have you ever wondered why we yawn?<br>(A) However, recent studies show another possible reason. Yawning may help cool down our brains, just like a fan cools a computer.<br>(B) For a long time, people believed that we yawn because our bodies need more oxygen.<br>(C) This idea may explain why people yawn more often in warm rooms: their brains get too hot there.</div>`, o: ['(A)-(C)-(B)', '(B)-(A)-(C)', '(B)-(C)-(A)', '(C)-(B)-(A)'], a: 1, why: '오랫동안의 생각(B) → However로 새로운 이유(뇌 식히기) 제시(A) → This idea가 뇌를 식힌다는 생각으로 따뜻한 방의 하품을 설명(C).' },
    { lv: 4, q: `글의 흐름으로 보아, 다음 문장이 들어가기에 가장 알맞은 곳은?<div class="passage">Because of this, they named the cat "Lucky."<br><br>🐈❄️ One cold winter night, the Park family heard a small sound outside the door. ( ① ) When they opened it, they found a tiny kitten shivering in the snow. ( ② ) They brought it inside and gave it warm milk. ( ③ ) The next day, the vet said the kitten was very lucky, because it could not have survived until morning outside. ( ④ ) Today, Lucky is a big, healthy cat who loves sleeping by the heater.</div>`, o: ['①', '②', '③', '④'], a: 3, why: 'this는 수의사가 "고양이가 아주 운이 좋았다"고 한 말을 가리키고, 뒤 문장에서 처음으로 Lucky라는 이름이 쓰이므로 ④가 알맞다.' },
    { lv: 4, q: `다음 글 바로 뒤에 이어질 내용으로 가장 알맞은 것은?<div class="passage">🛒📢<br>Dear Customers, thank you for shopping at Fresh Mart. We are sorry to tell you that our store will be closed from March 3 to March 10 for repairs. During this time, you can still order food on our website, and we will deliver your order for free. When we open again, our store will be bigger and brighter. To celebrate, we are planning some special events for our customers. Here are the details.</div>`, o: ['가게 수리 기간의 휴무 안내', '재개장 기념 특별 행사의 세부 내용', '무료 배달 서비스를 끝내는 이유', '다른 지점의 위치'], a: 1, why: '마지막 두 문장에서 재개장 기념 특별 행사를 준비 중이라고 하고 Here are the details로 이어지므로, 행사의 세부 내용이 나온다. ①은 이미 앞에서 말했다.' },
    { lv: 5, q: `주어진 글 다음에 이어질 글의 순서로 가장 알맞은 것은?<div class="passage">📜 Before Hangeul was created, most Koreans had trouble reading and writing.<br>(A) He wanted letters that anyone could learn easily. With his scholars, he worked hard, and in 1443, Hangeul was finally created.<br>(B) They had to use Chinese characters, which were very difficult to learn and took many years to master.<br>(C) To solve this problem, King Sejong decided to make new letters for his people.</div>`, o: ['(C)-(A)-(B)', '(A)-(B)-(C)', '(B)-(C)-(A)', '(B)-(A)-(C)'], a: 2, why: '(B)의 They는 주어진 글의 Koreans이다. (B)의 어려움이 (C)의 this problem이고, (C)에서 세종대왕이 나와야 (A)의 He가 그를 가리킬 수 있다.' },
    { lv: 5, q: `글의 흐름으로 보아, 다음 문장이 들어가기에 가장 알맞은 곳은?<div class="passage">So how do they find food in the dark?<br><br>🦇🌙 Bats are the only mammals that can truly fly. ( ① ) Most bats hunt insects at night, but they have poor eyesight. ( ② ) They make high sounds and listen for the echoes that bounce back from objects. ( ③ ) From the echoes, they can tell where an insect is and how fast it is moving. ( ④ ) In fact, some bats can catch hundreds of insects in an hour.</div>`, o: ['①', '②', '③', '④'], a: 1, why: '밤에 사냥하지만 눈이 나쁘다는 문제(②의 앞) 다음에 "그럼 어떻게 찾을까?"라고 묻고, 소리와 메아리로 찾는 방법(②의 뒤)이 이어진다.' },
    { lv: 5, q: `다음 글 바로 뒤에 이어질 내용으로 가장 알맞은 것은?<div class="passage">🌦️🐦<br>Most of us check a weather app before we go out. But long before apps existed, people found other ways to predict the weather. Farmers watched the sky and the animals around them. For example, when swallows flew low, they believed rain was coming. Interestingly, some of these old beliefs have a scientific reason. Let's look at why swallows fly low before it rains.</div>`, o: ['날씨 앱을 사용하는 방법', '농부들이 키우는 동물의 종류', '제비가 비 오기 전에 낮게 나는 과학적 이유', '제비가 따뜻한 곳으로 이동하는 시기'], a: 2, why: "마지막 문장 Let's look at why swallows fly low before it rains가 다음 내용을 예고한다." },
  ],
});

ENG.add('m2', '독해: 안내문·도표 읽기', {
  sub: '항목 이름·조건·숫자를 정확히 대조하기',
  kw: ['안내문', '도표', 'Admission', 'Registration', 'under / or older', '증가·감소', '두 배', '계산'],
  sections: [
    { h: '안내문의 구성과 자주 나오는 말',
      p: '안내문은 <b>항목 이름</b> 뒤에 정보가 짧게 정리되어 있다. 항목 이름의 뜻을 알면 필요한 정보를 바로 찾을 수 있다.',
      table: { head: ['항목', '뜻', '예'], rows: [['Date / When', '날짜·때', 'July 24–25'], ['Place / Location / Venue', '장소', 'School Science Lab'], ['Who / Eligibility', '참가 대상', '1st and 2nd graders'], ['Fee / Admission', '참가비 / 입장료', '10,000 won (lunch included)'], ['Registration / How to apply / Deadline', '등록 / 신청 방법 / 마감', 'Sign up by July 15'], ['Note / Notice', '참고·주의 사항', 'Bring your own water.']], cap: '안내문 항목' },
      ex: [['Admission is free for children under 7.', '7세 미만 어린이는 입장료가 무료이다.'], ['You must sign up by July 15.', '7월 15일까지 신청해야 한다.']] },
    { h: '도표 읽기와 비교 표현',
      p: '도표(표·그래프) 문제는 <span class="hl">제목 → 항목 → 단위 → 숫자</span> 순서로 읽고, 보기의 비교 표현을 숫자로 직접 확인한다. %인지 사람 수인지, 몇 년도인지 꼭 확인한다.',
      table: { head: ['표현', '뜻', '확인 방법'], rows: [['increase / rise', '증가하다', '앞 숫자 < 뒤 숫자'], ['decrease / go down', '감소하다', '앞 숫자 > 뒤 숫자'], ['the highest / the lowest', '가장 높은 / 낮은', '같은 값이 둘 이상이면 주의'], ['twice / double', '두 배', '정확히 ×2 (more than twice는 2배 초과)'], ['the same as', '~와 같은', '두 값이 일치'], ['percentage points', '%p (퍼센트 차이)', '15% → 30%는 15%p 증가']], cap: '도표 문제의 비교 표현' },
      ex: [['The number of visitors went down a little in 2023.', '2023년에 방문객 수가 조금 줄었다.'], ['The percentage for games doubled.', '게임의 비율이 두 배가 되었다.']] },
    { h: '조건 읽기와 자주 하는 실수',
      p: '안내문의 정답·오답은 <b>조건과 예외</b>에서 갈린다. 나이 제한, 할인 조건, 무료 조건, 늦을 때 추가 요금 같은 말을 놓치지 않는다.',
      table: { head: ['조건 표현', '뜻', '자주 하는 실수'], rows: [['under 7', '7세 미만 (7세는 해당 안 됨)', '7세도 무료라고 생각'], ['13 or older / at least', '13세 이상 / 최소', '12세도 된다고 생각'], ['up to 4', '최대 4명', '4명 초과도 된다고 생각'], ['except / closed on', '~을 제외하고 / ~에 휴무', '휴무 요일을 놓침'], ['only ~ count', '~만 인정', '조건에 안 맞는 것까지 셈'], ['for every 30 minutes', '30분마다', '추가 요금을 한 번만 더함']] },
      ex: [['You must be 13 or older to rent a bike alone.', '혼자 자전거를 빌리려면 13세 이상이어야 한다.'], ['Only books from our library count.', '우리 도서관 책만 인정된다.']],
      warn: '계산 문제는 표의 가격 → 할인·무료 조건 → 추가 요금 순서로 적어 가며 계산한다.' },
  ],
  bank: [
    { lv: 1, q: '안내문에 쓰인 "Admission"의 뜻으로 알맞은 것은?', o: ['입장료', '장소', '마감일', '준비물'], a: 0, why: 'Admission은 입장(료)을 뜻한다. 장소는 Place/Location, 마감일은 Deadline이다.' },
    { lv: 1, q: '"Registration Deadline: May 5"가 뜻하는 것은?', o: ['행사 날짜', '결과 발표일', '신청 마감일', '개장 시간'], a: 2, why: 'Registration은 등록(신청), Deadline은 마감일이다.' },
    { lv: 1, q: '"Children under 7 are free."에 따르면 무료인 사람은?', o: ['7살 이상 어린이', '모든 어린이', '부모님', '7살 미만 어린이'], a: 3, why: 'under 7은 "7세 미만"이므로 7살은 포함되지 않는다.' },
    { lv: 2, q: `다음 안내문의 내용과 일치하지 <b>않는</b> 것은?<div class="passage">🧪🔬 Science Camp<table><tr><th>Date</th><td>July 24–25</td></tr><tr><th>Place</th><td>School Science Lab</td></tr><tr><th>Who</th><td>1st and 2nd graders (20 students)</td></tr><tr><th>Fee</th><td>10,000 won (lunch included)</td></tr><tr><th>Sign up</th><td>Room 201 by July 15</td></tr></table>Come and do fun experiments with your friends!</div>`, o: ['캠프는 이틀 동안 열린다.', '참가비에 점심이 포함되어 있다.', '3학년도 참가할 수 있다.', '7월 15일까지 신청해야 한다.'], a: 2, why: '참가 대상은 1, 2학년(1st and 2nd graders)이므로 3학년은 참가할 수 없다.' },
    { lv: 2, q: `다음 도표에서 학생 수가 가장 많은 항목은?<div class="passage">📱 Hours Spent on Smartphones per Day (Class 2-3)<table><tr><th>Time</th><th>Students</th></tr><tr><td>less than 1 hour</td><td>4</td></tr><tr><td>1–2 hours</td><td>10</td></tr><tr><td>2–3 hours</td><td>12</td></tr><tr><td>more than 3 hours</td><td>6</td></tr></table>The class has 32 students in total.</div>`, o: ['2–3 hours', 'less than 1 hour', '1–2 hours', 'more than 3 hours'], a: 0, why: '2~3시간이 12명으로 가장 많다. 32는 반 전체 학생 수이다.' },
    { lv: 2, q: `다음 안내문을 보고, 학생 2명과 어른 1명이 수영장에 갈 때 내야 할 돈은?<div class="passage">🏊 Blue Wave Pool<table><tr><th>Ticket</th><th>Price</th></tr><tr><td>Adult</td><td>5,000 won</td></tr><tr><td>Student</td><td>3,000 won</td></tr></table>Open every day 6 a.m.–9 p.m.</div>`, o: ['8,000 won', '11,000 won', '10,000 won', '13,000 won'], a: 1, why: '학생 3,000원 × 2 = 6,000원, 어른 5,000원을 더하면 11,000원이다.' },
    { lv: 3, q: `다음 안내문을 읽고 알 수 <b>없는</b> 것은?<div class="passage">🎤✨ Talent Show Auditions<br>Do you have a special talent? Singing, dancing, magic, or comedy — anything is OK!<br>Date: Friday, April 12, 3–6 p.m.<br>Place: School Auditorium<br>Who: All students (alone or in a team of up to 4)<br>How to apply: Fill out the form on the school website by April 5.<br>Each performance must be shorter than 3 minutes.<br>Note: Bring your own music on a USB.</div>`, o: ['오디션 장소', '팀의 최대 인원', '오디션 심사위원', '공연 제한 시간'], a: 2, why: '장소(School Auditorium), 최대 인원(up to 4), 제한 시간(3분 미만)은 나오지만 심사위원은 나오지 않는다.' },
    { lv: 3, q: `다음 도표의 내용과 일치하는 것은?<div class="passage">🎨⚽💻🎵 Favorite After-School Activities<table><tr><th>Activity</th><th>1st grade</th><th>2nd grade</th></tr><tr><td>Sports</td><td>30%</td><td>25%</td></tr><tr><td>Music</td><td>20%</td><td>15%</td></tr><tr><td>Coding</td><td>15%</td><td>30%</td></tr><tr><td>Art</td><td>35%</td><td>30%</td></tr></table></div>`, o: ['1학년은 코딩을 가장 좋아한다.', '2학년에서 코딩과 미술의 비율이 같다.', '음악은 1학년보다 2학년에서 비율이 높다.', '두 학년 모두 운동의 비율이 가장 높다.'], a: 1, why: '2학년의 코딩과 미술은 둘 다 30%이다. 1학년은 미술(35%)이 가장 높고, 음악은 1학년(20%)이 2학년(15%)보다 높다.' },
    { lv: 3, q: `다음 안내문을 보고, 엄마와 15살 Sohee, 5살 동생이 함께 갈 때 내야 할 입장료의 합은?<div class="passage">🔭 Hanul Science Museum<br>Open: Tue–Sun, 9 a.m.–6 p.m. (closed on Mondays)<table><tr><th>Ticket</th><th>Price</th></tr><tr><td>Adults</td><td>8,000 won</td></tr><tr><td>Teens (13–18)</td><td>5,000 won</td></tr><tr><td>Children (7–12)</td><td>3,000 won</td></tr><tr><td>Under 7</td><td>Free</td></tr></table>Groups of 10 or more: 20% off</div>`, o: ['13,000 won', '16,000 won', '11,000 won', '10,400 won'], a: 0, why: '어른 8,000원 + 청소년 5,000원 + 7세 미만 무료 = 13,000원이다. 세 명이므로 단체 할인(10명 이상)은 받을 수 없다.' },
    { lv: 4, q: `다음 안내문을 보고, 14살 Sumin이 자전거를 3시간 빌렸다가 1시간 늦게 반납했을 때 낸 돈의 합은?<div class="passage">🚲 Riverside Bike Rental<table><tr><th>Time</th><th>Price</th></tr><tr><td>1 hour</td><td>2,000 won</td></tr><tr><td>3 hours</td><td>5,000 won</td></tr><tr><td>1 day</td><td>10,000 won</td></tr></table>• Helmets are free.<br>• You must be 13 or older to rent a bike alone.<br>• If you return the bike late, you pay 1,000 won for every 30 minutes.</div>`, o: ['5,000 won', '6,000 won', '8,000 won', '7,000 won'], a: 3, why: '3시간 요금 5,000원에, 1시간 늦었으므로 30분마다 1,000원씩 2번 = 2,000원을 더해 7,000원이다. 헬멧은 무료이다.' },
    { lv: 4, q: `다음 도표를 설명한 글에서 도표의 내용과 일치하지 <b>않는</b> 문장은?<div class="passage">🌳 Visitors to Green Lake Park (unit: thousand people)<table><tr><th>Year</th><th>2021</th><th>2022</th><th>2023</th><th>2024</th></tr><tr><td>Visitors</td><td>40</td><td>55</td><td>50</td><td>80</td></tr></table>① The number of visitors increased from 2021 to 2022. ② In 2023, the number of visitors went down a little. ③ The park had the most visitors in 2024. ④ The number of visitors in 2024 was more than twice that of 2021.</div>`, o: ['①', '②', '③', '④'], a: 3, why: '2024년(80)은 2021년(40)의 정확히 두 배이므로 "두 배보다 많다(more than twice)"는 틀리다.' },
    { lv: 4, q: `다음 안내문의 내용과 일치하지 <b>않는</b> 것은?<div class="passage">🌊🏮 Blue Beach Summer Night Market<br>Dates: Every Friday and Saturday in August<br>Time: 7 p.m.–11 p.m.<br>What to enjoy: street food, handmade goods, and live music<br>Notes:<br>• The market will be closed if it rains.<br>• Pets are welcome but must be on a leash.<br>• There are no trash cans at the market, so please take your trash home.</div>`, o: ['8월 금·토요일에 열린다.', '반려동물은 데려올 수 없다.', '비가 오면 열리지 않는다.', '쓰레기는 각자 가져가야 한다.'], a: 1, why: 'Pets are welcome but must be on a leash라고 했으므로 목줄을 하면 반려동물을 데려올 수 있다.' },
    { lv: 5, q: `다음 안내문을 읽고, 도서관 책 12권과 직접 산 책 3권을 읽고 15권 모두 60단어씩 감상문을 쓴 Jiho가 받을 상은?<div class="passage">📚🏅 Summer Reading Challenge<br>Read books from June 20 to August 20 and write a short review of each book on the library website.<table><tr><th>Books Read</th><th>Prize</th></tr><tr><td>5–9</td><td>Bookmark</td></tr><tr><td>10–19</td><td>Library Bag</td></tr><tr><td>20 or more</td><td>Bookstore Gift Card</td></tr></table>• Only books from our library count.<br>• Each review must be at least 50 words long.</div>`, o: ['Bookmark', 'Bookstore Gift Card', 'Library Bag', 'No prize'], a: 2, why: '도서관 책만 인정되므로 12권이 인정되고, 감상문도 50단어 이상이다. 10~19권이므로 Library Bag을 받는다.' },
    { lv: 5, q: `다음 도표의 내용과 일치하는 것은?<div class="passage">💰 How Students Spend Their Allowance<table><tr><th>Item</th><th>2023</th><th>2025</th></tr><tr><td>Snacks</td><td>35%</td><td>25%</td></tr><tr><td>Saving</td><td>30%</td><td>30%</td></tr><tr><td>Clothes</td><td>20%</td><td>15%</td></tr><tr><td>Games</td><td>15%</td><td>30%</td></tr></table></div>`, o: ['Snacks had the highest percentage in both years.', 'Saving had a lower percentage in 2025 than in 2023.', 'Clothes had a higher percentage in 2025 than in 2023.', 'The percentage for games doubled from 2023 to 2025.'], a: 3, why: '게임은 15%에서 30%로 두 배가 되었다. 2025년에는 간식(25%)이 가장 높지 않고, 저축은 30%로 같으며, 옷은 20%에서 15%로 줄었다.' },
    { lv: 5, q: `다음 안내문의 내용과 일치하는 것은?<div class="passage">🏫📖 Hana Middle School Library — Vacation Hours<table><tr><th>Period</th><th>Days</th><th>Hours</th></tr><tr><td>Dec 26 – Jan 31</td><td>Mon – Fri</td><td>10 a.m. – 4 p.m.</td></tr><tr><td>Feb 1 – Feb 28</td><td>Mon, Wed, Fri</td><td>10 a.m. – 2 p.m.</td></tr></table>• The library is closed on weekends and holidays.<br>• During vacation, you can borrow up to 5 books for 3 weeks.</div>`, o: ['1월에는 토요일에도 이용할 수 있다.', '방학 중에는 책을 2주 동안 빌릴 수 있다.', '2월에는 화요일에 문을 열지 않는다.', '2월에는 오후 4시까지 이용할 수 있다.'], a: 2, why: '2월에는 월·수·금에만 열므로 화요일에는 열지 않는다. 주말은 휴관, 대출 기간은 3주, 2월은 오후 2시까지이다.' },
  ],
});
